if not (flavor == "retail") then return end
local pack = WordHunterWoW_QuestSources and WordHunterWoW_QuestSources["multilanguage-retail"]
if not pack then return end
pack.loaded = true
local quests = pack.locales.enUS

quests[58630] = { id = 58630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crown of the Harvesters", description = "Power you seek to focus is volatile. Need the Eternal Forge's flames to get it done. \n\nWithout the blessing of the flames, I fear it will overwhelm the wearer.\n\nBring venthyr friend. His magic will prove useful. Need you to absorb impurities. \n\n<Mikanikos hands you an elegant container.>\n\nUse this to capture imperfections that burn off during the process.", progress = "It is done then?", completion = "Perfection.", objectives = "Meet Mikanikos at the Eternal Forge. Then, assist him with forging the Crown of the Harvesters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58631] = { id = 58631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into Dreams", description = "I cannae believe that Ra-den sacrificed himself to save us. We cannae give up on him!\n\nThere must be a way tae find out where he went. \n\nLet's see if MOTHER can track him down!", progress = "We're runnin' outta time!", completion = "That portal must be the entrance tae N'Zoth's realm.\n\nThis may be our only chance tae get Ra-den back and take out N'Zoth once and fer all!", objectives = "Speak with MOTHER in the Chamber of Heart to track Ra-den's location.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58632] = { id = 58632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ny'alotha, the Waking City: The Corruptor's End", description = "Usin' the mogu's research, MOTHER and Ra-den found a way tae focus the forge's Origination Protocol through the Chamber of Heart. The only problem was findin' out where tae shoot it.\n\nThat is, until now.\n\nTake these anchors and head through that portal. Ye'll need tae find some prominent landmarks tae place 'em so we can focus the weapon. Once they're set, we'll be ready tae fire.\n\nYe'll only get one shot. Make it count!", progress = "It's time tae blast N'Zoth back tae the void he came from!", completion = "Ye did it! N'Zoth's forces are scattered and his grip on our world is fading!\n\nYe truly are the champion of Azeroth!", objectives = "Defeat N'Zoth in Ny'alotha, the Waking City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58634] = { id = 58634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Opening the Gateway", description = "The fabric of reality is torn. But there's no need for me to tell you that, {name}. You've seen it firsthand. \n\nIt's only a matter of time before these realities become one, veiled in eternal darkness. Instead of hiding, perhaps it's time we embraced the darkness.\n\nWith the help of our titan friend here we may be able to thread the needle of this reality through the fabric of another, creating a bridge of sorts.\n\nAfter all, the key to understanding an enemy's weakness is to understand their intentions.", progress = "Uncertainty comes before discovery.", completion = "The time has come for us to confront the darkest of these manifestations.", objectives = "Speak with MOTHER to establish the Tenebrous Gateway in the Chamber of Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58636] = { id = 58636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes on the Amathet", description = "On behalf of the Explorers' League, I'd like tae thank ye for helping establish the Uldum Accord and buying us some cooperation from Ramkahen.\n\nIn the interest of better understanding our foes, Ramkahen has allowed the exploring of the Amathet tombs. Unfortunately, though, their forces are spread too thin to provide protection.\n\nI was hopin' ye could help out with that. \n\nThink ye could spare some time tae see what they're all about? We can start with an aerial look.", progress = "To the skies!", completion = "So much tae take in! I just wish it wasn't so hard tae write notes on gryphon-back.\n\nStill, I think we've only uncovered the tip of the iceberg.", objectives = "Scout the Amathet territories with High Explorer Dellorah in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58638] = { id = 58638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Deeper Dive", description = "Something just isn't adding up about these Amathet. Why would protectors of titan works attack and damage the Forge of Origination?\n\nI think we need tae take a closer look. I think I saw a monument on the terrace over there. Perhaps the writings there could tell us more about these tol'vir.", progress = "I'm ready when ye are, {class}.", completion = "This monument was a good start, but it still doesn't explain what we're looking for.\n\nFortunately, uncovering mysteries is what the Explorer's League does best!", objectives = "Defend High Explorer Dellorah as she deciphers the Amathet Monument at Sunstone Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58639] = { id = 58639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buried History", description = "Since the Amathet came from this region, it would only stand to reason that artifacts from their civilization would be left behind here, hidden beneath the sands.\n\nIt looks like it's time for a good old-fashioned dig!\n\nThe dunes near here must have covered up a large swath of the Amathet's former territory. Let's see what we can dig up there!", progress = "What have ye turned up?", completion = "Yes! The markings on these artifacts confirm my hypothesis. \n\nThere's definitely more to this than we first thought.", objectives = "Uncover and collect 6 Amathet Artifacts in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58640] = { id = 58640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Crack in the Armor", description = "The artifacts you helped excavate show the Amathet as a tribe who prided themselves on protecting the works of the titans. \n\nThis confirms our assumptions, and indicates that something drastic must have happened to them to cause them to damage the very works they swore to protect.\n\nWe should continue to track down their writings. I think I saw a more recent monument outside the Halls of Origination.", progress = "I cannae wait tae solve this mystery!", completion = "Someone, or something, has been manipulating the Amathet from within. \n\nSounds familiar, don't you think?", objectives = "Defend High Explorer Dellorah as she deciphers the Amathet Monument outside the Halls of Origination.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58641] = { id = 58641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seekers of Corruption", description = "If anyone would know more about the \"corruption\" the tablet spoke of, it would be the Suntouched that were put in charge of rooting it out.\n\nOf course, I doubt they'll be willing to turn over any information voluntarily.\n\nLuckily for me, you're a bit of a specialist at brute force investigation, aren't you?", progress = "Found anything from the Suntouched?", completion = "So the Amathet aren't working with N'Zoth after all! That's a relief!\n\nOf course, that doesn't make them any less hostile to us, but it's a start!", objectives = "Collect the Sun King's Decree from Suntouched Amathet in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58642] = { id = 58642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shared Goals", description = "The decree you found made mention of a plan to defeat the Old Gods. \n\nI know that the Amathet aren't likely to work with us toward that goal, but if they have a plan tae take out N'Zoth, it's worthwhile for us tae look at it.\n\nThe decree mentions the Engine of Ascension. I think that might be what they call that solar empowering device we saw earlier. We should take a peek underneath and see if we can figure out what they're planning!", progress = "Let's see what we can find in the Chamber of the Stars.", completion = "These Amathet are off their rockers! \n\nThey've decided that Azeroth is too far gone for saving!", objectives = "Defend High Explorer Dellorah as she deciphers the Amathet Tablets within the Chamber of the Stars.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58643] = { id = 58643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mutually Assured Destruction", description = "The Amathet want tae re-take the Forge of Origination so they can use it tae end all life on Azeroth, Old God or otherwise! \n\nThey could strike at any moment. We have tae warn the defenders of the Forge!", completion = "The Amathet... charged on our position.  \n\nWe were... outmatched...", objectives = "Warn the defenders of the Halls of Origination about the Amathet's plan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58645] = { id = 58645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A World Worth Saving", description = "We could not stand against them. Their warriors... wreathed in the sun's flames...\n\nThey want the forge... to end all...\n\nGo... I will... endure...", completion = "You did it! I cannae believe that we were mere moments away from the end of life as we know it!\n\nThank ye for yer help with my research, {class}. If ye weren't here I don't want tae know how this would've ended!\n\nNow, if ye'll excuse me, it's goin' tae take weeks tae catalogue all we've found!", objectives = "Stop the Amathet from taking the Halls of Origination.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58646] = { id = 58646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chew On This!", description = "These mangy hyena will gnaw on anything they dig up, including priceless artifacts!\n\nWe cannae allow the history of Uldum tae go tae the dogs, so tae speak.\n\nI'm afraid we're gonna have tae thin out their numbers.", progress = "Did ye take care of the hyenas?", completion = "That was a regrettable thing, but necessary.\n\nThank ye, {name}.", objectives = "Kill 8 Scavenging Dunerunners in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58647] = { id = 58647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broken Webs", description = "My husband once served our people as the Speaker of Elune--until he became the Night Warrior. His feelings on the matter are... complicated, to say the least.\n\nSpriggans have been ripping the garden's soulwebs. Would you please help me repair them? I will recount our story as we work.", progress = "Just one more.", completion = "Thank you, {name}. This task is much easier with help.\n\n\n\nI hope you do not think too poorly of Thiernax. His history with the Night Warrior ritual is rife with misplaced guilt and remorse, but I am certain I can get him to see sense and offer his aid.", objectives = "Help repair soul webs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58654] = { id = 58654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Plea to the Harvesters", description = "You come during strange times. Every day the tithes we must pay to the Tithelord increase, and our ability to get anima dwindles. \n\nWhat souls we have to work with here are near their final judgment and we lack the resources to harvest them without endangering the hamlet.\n\nIf you have the ear of Lord Chamberlain, then you might be able to pass a message to the Master himself. \n\nHere, take this letter. Please see that it makes it to the hands of the Chamberlain.", completion = "Oh, the peasants have asked for help have they? \n\nThose who are loyal would know that sacrifices are essential to the survival of Revendreth. Yes, these are dark times with anima and new souls both being in short supply. \n\nBut we must all do our part, no matter how painful.", objectives = "Deliver Mihaela's Note to the Lord Chamberlain.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58656] = { id = 58656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heavy is the Head...", description = "Crown is unstable due to Sire's lingering influence from the medallions. A test run should solve.\n\nSocketed one of your medallions. Witness its power focused into a weapon of destruction. \n\nPerfect opportunity. Forsworn finished colossi construction. Destroy them.  Bring the Forsworn the end they crave. \n\nCareful. Theotar informed me how powerful magic this is. The crown will hunger, must control it.", progress = "Bring the Forsworn the destruction they crave.", completion = "You're alive. The crown started to feed off your soul.\n\nLooks like there is still work to do. Mikanikos says the Sire's influence remains present in the crown. \n\nHe says he has a plan.", objectives = "Test the Crown of the Harvesters and defeat the Operational Colossi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58660] = { id = 58660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burrowing Terrors" }
quests[58661] = { id = 58661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burrowing Terrors" }
quests[58662] = { id = 58662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burrowing Terrors" }
quests[58664] = { id = 58664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ultimate Makeover", description = "We now control the Apparatus of Abominable Construction! We can use it to create new constructs to contain worthy souls.\n\nEmeni is the best choice to be first. Her combat skills are unmatched, and you may need her to help secure the Stitchyard.\n\nYou will assist me in rebuilding Emeni's construct.", objectives = "Help Rathan rebuild Emeni's Construct.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58665] = { id = 58665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rebellious Souls", description = "Please hear us out, Maw Walker.\n\nWhen Margrave Gharmal launched his attack on Bastion, there were many, such as Emeni and myself, that opposed his actions. \n\nFearing dissent, Gharmal removed many souls from their constructed bodies and imprisoned them. Emeni escaped the prison, but most did not.\n\nHelp us free the other souls, and we can build you an army of constructs far greater than any that serve Gharmal.", completion = "Do not let Emeni's sour disposition deter you. Your aid is greatly appreciated, Maw Walker!", objectives = "Meet Rathan and Emeni at Sixfold Recluse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58667] = { id = 58667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Obsidian Extraction" }
quests[58668] = { id = 58668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find The Way", description = "I apprenticed at the Stitchyard for many eons. I even worked in the Body Banks with surgeon Stitchflesh to design Emeni's last construct.\n\nIf we gain control of the Body Banks, we will have the parts necessary to rebuild Emeni and create new bodies for other souls we rescue. \n\nLead us to there and we'll see if we can get it operational.", completion = "I never imagined myself returning to this place.", objectives = "Lead Rathan and Emeni to the Body Banks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58669] = { id = 58669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Pruning", description = "Spriggans sometimes invade the garden to spread mischief and mayhem. There is no end to the trouble they bring with them.\n\nUsually, the Wild Hunt keeps them in check... but their huntsmen and huntresses have had far more pressing concerns as of late. Thiernax and I have been helping to keep the garden clear, but he's run off somewhere to brood.\n\n<Qadarin shakes his head.>\n\nYou would be doing me a favor if you helped me clear the Queen's garden of these vermin.", progress = "At least here we only have to worry about spriggans. Other parts of the forest are not so fortunate.", completion = "Hopefully they'll get the message and go back from whence they came!", objectives = "Slay 15 Sicklethorn spriggan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58670] = { id = 58670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Slaughter Daughter", description = "When I was locked up, I made a list of all the constructs that betrayed me... it is a lengthy list!\n\nHelp me teach these constructs the mistake they made. I want to destroy everyone on my list, along with Yardmaster Pralak, who is number one on the list!", completion = "I feel like we've made our point, {name}.", objectives = "Help Emeni slaughter everyone on her list.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58671] = { id = 58671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bottled Up Inside", description = "There were many souls that opposed Margrave Gharmal's attack on Bastion. Those of us that spoke out, were stripped our bodies, imprisoned in the Etheric Vault, till our souls faded away, starved of anima.\n\nMy friends are still imprisoned in the vaults. We will free them, and build an army of constructs to fight for you!", completion = "We make a good team, {name}.", objectives = "Rescue 10 Imprisoned Souls in the Etheric Vault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58672] = { id = 58672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gathering of Champions", description = "The leaders of the Horde are gathering together in Orgrimmar to nominate a new Warchief of the Horde.\n\nAs a champion of the Horde, your presence at the meeting has been requested. The gathering will be held at the embassy in Orgrimmar.\n\nI will be going on ahead. Come speak with me when you arrive in Orgrimmar, I'll be waiting with the others.\n\nMake haste, champion. The future of the Horde is about to be decided...", completion = "You got here just in time. The meeting is about to begin.", objectives = "Speak with Valeera Sanguinar in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58673] = { id = 58673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief of the Horde", description = "The meeting to decide the next Warchief of the Horde is about to begin.\n\nThe other leaders of the Horde have already arrived. They are waiting for you inside the embassy.\n\nSpeak with me when you are ready, and we will greet the others together.", completion = "It has been decided, then. There will no longer be a Warchief of the Horde.\n\nIt seems that we have been made witnesses to the beginning of a new era...", objectives = "Witness the gathering of champions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58674] = { id = 58674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gathering of Champions", description = "King Wrynn has called for an audience with the Alliance leaders in Stormwind.\n\nYour presence at the meeting has been specifically requested. The gathering will be held at the embassy.\n\nCome speak with me when you arrive in Stormwind, I'll be waiting with the others.\n\nDo hurry, {name}. It would be ill-advised to keep the king waiting...", completion = "You got here just in time. The king is about to begin his address.", objectives = "Speak with Master Mathias Shaw in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58675] = { id = 58675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Price of Peace", description = "The king will be addressing us shortly with news from his diplomatic mission to the Horde.\n\nThe other leaders of the Alliance have already arrived. I am sure they are eager to hear what King Wrynn has to say.\n\nSpeak with me when you are ready, and we will greet the king together.", completion = "Hmm... the meeting did not seem to go quite as the king expected. We know where Genn and Tyrande stand, but I wonder what the others have to say.", objectives = "Witness King Wrynn's address.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58676] = { id = 58676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dormant Destroyer" }
quests[58677] = { id = 58677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skin in the Game", description = "This task is probably above your capabilities, but listen anyway.\n\nAs a construct I was feared throughout the Shadowlands. The magnificent skin of my construct was impervious to mortal weapons, it was a work of art that took years to perfect.\n\nWhen I was removed from my construct, it was Faldo Iscar who took great delight in stealing that skin. He keeps it on himself as a souvenir.\n\nKill Faldo Iscar, and get my skin back!", progress = "When I was alive, you might have been my friend... or maybe my dinner.", completion = "My cold blood warms to you. You may be a suitable ally.", objectives = "Emini's Magnificent Skin obtained", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58679] = { id = 58679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dormant Destroyer" }
quests[58680] = { id = 58680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loose Threads", description = "We're missing a few tools and parts for sewing a construct. We need these items if we're to rebuild my construct!\n\nSearch the surrounding area. See if you can find us what we need.\n\nSearch tables for the Skewering Needles, you can find haulers that carry Razorthread Spools, and look for Clotting Patches on constructs you kill.", progress = "You are good at this.", completion = "You should consider a constructed body, perhaps I can design you one someday.", objectives = "Locate Skewering Needles, Razorthread Spools and Clotting Patches.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58686] = { id = 58686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapon of Mass Construction", description = "We are in luck!\n\nSurgeon Stitchflesh and his assistant have not returned from Bastion.  The entire Stitchyard is lightly guarded.\n\nWe must work fast. See if you can get the equipment operational. Once it is active, we can begin the construction process.", progress = "We will control the means of production!", completion = "We're almost done! Just one more step to complete the construction!", objectives = "Get the assembly lab operational.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58704] = { id = 58704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Garden of Night", description = "That should take care of things out here. Now we must tend to the inner garden. Once we're done, I'll sort out my recalcitrant husband.\n\nHopefully, any remaining spriggans will have cleared out on their own after hearing us dispatch the others.", progress = "This is my fault... just like before...", completion = "I should have never left! He's told me time and again that I should face my...\n\nNever mind. I can deal with that later.\n\nThe situation would have been much more dire if the two of you were not here.", objectives = "Slay spriggans in the central garden.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58705] = { id = 58705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Empress Shek'zara" }
quests[58706] = { id = 58706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dressing the Kill", description = "<Huln listens to your explanation, then pauses thoughtfully.>\n\nI believe I understand, {name}. But I cannot help you right now.\n\nAllow me to explain. In the meantime, will you carve up this carcass with me? Your prey always has something to teach you.", progress = "The more quickly you carve, the more quickly I can help you.", completion = "Excellent. This confirms my suspicions.", objectives = "Help Huln Highmountain carve up the devourer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58707] = { id = 58707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sorting Through Visions" }
quests[58708] = { id = 58708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fame Waits for Gnome One", description = "Tinkmaster Overspark requests your assistance on an important research expedition. \n\nWorking with the esteemed Tinkmaster will certainly be of benefit to your career. It's done wonders for mine!", completion = "Now we can begin the expedition.", objectives = "Meet with Tinkmaster Overspark in Boralus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58714] = { id = 58714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forest Has Eyes", description = "That dream! With the teeth and the claws and the heart... heart-wrenching sacrifice?\n\n<Moonberry chokes up for a moment then collects herself.>\n\nSorry! While we were in dreamland, possessed spies have snuck into Hibernal Hollow! \n\nThey must be hunted down and slain before they can report back on the grove's defenses.\n\nHere, borrow a bit of my magic. Seek out the ones hidden in the shadows and smite them!", progress = "Have you uncovered all those pesky spies yet?", completion = "These Drust are bold to send spies into my grove! Very bold... and very foolish.", objectives = "Slay hidden Possessed Spies throughout Hibernal Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58717] = { id = 58717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bell of Remembrance", description = "<The bell is scratched and damaged. You remember the Curator being very interested in this item.\n\nMaybe someone at the Crypt of the Forgotten will know more.>", completion = "Greetings, Maw Walker.\n\nWhy have you come to me? I have heard so much about you.", objectives = "Find someone who knows more about the bell at the Crypt of the Forgotten.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58719] = { id = 58719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Droman's Call", description = "Our enemies close in swiftly, {name}. We must sound the call to defend the grove!\n\nUse this horn to call upon our protectors. Summon the Wild Hunt to slay those who would attack us.", progress = "The Hunt will hear our call and ride to defend the grove!", completion = "The Wild Hunt rides to our aid... but not from the west?\n\nThat is where Hunt-Captain Korayn was tracking a dangerous foe. She and her hunting party must have been waylaid.", objectives = "Use the Droman's Horn to summon the Wild Hunt at the entrances to the grove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58720] = { id = 58720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing!", description = "The Wild Hunt has answered the call to defend us... except for Hunt-Captain Korayn and her forces.\n\nShe had led her hunting party to the west, on the trail of a powerful foe. They may have encountered trouble.\n\nFind her and provide whatever aid she requires. \n\nWe need her hunters and her leadership if our defenses are to hold.", completion = "These Drust thought to send a force to strike us from behind. \n\n<Korayn smirks.>\n\nYour call brought my fellow huntsmen and huntresses to reinforce us. Our foes were the ones caught by surprise.", objectives = "Find Hunt-Captain Korayn on the Path of Rebirth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58721] = { id = 58721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Awaken the Dreamer", description = "Much of the Queen's focus has centered on the Grove of Awakening, where rejuvenated spirits emerge from their wildseeds and return to their worlds.\n\nPerhaps it is fitting you carry a wounded spirit with you.\n\n<Lord Herne studies Ysera's wildseed for a moment before a slow grin spreads across his face.>\n\nThis one fights with all of her being. Even now she clings to existence. \n\nCome, stranger, let us see what fate the Queen will decree for this one.", completion = "<The Winter Queen turns her gaze upon you.>\n\nHow curious to see someone like you in my forest.", objectives = "Travel to the Grove of Awakening.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58723] = { id = 58723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Court of Winter", description = "My Court informs me that you bear an important message.\n\nYou may now deliver it.", progress = "The ancient enemy has not been idle...", completion = "The Banished One stirs and Ardenweald's power withers in drought.", objectives = "Give the Primus's message to the Winter Queen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58724] = { id = 58724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Queen's Request", description = "Dire portents indeed. \n\nI have used what little anima we possess to save our groves and the spirits they nurture. So many were lost... all as the Heart of the Forest grew ever weaker.\n\nKeeping the Banished One bound within the Maw will require more anima than Ardenweald can spare.\n\n<The Queen considers for a moment.>\n\nSire Denathrius is a master of anima extraction. Journey to Revendreth and inform him of our plight. I know he will lend us his aid.\n\nYour allies in Oribos can open the way.", completion = "What has transpired in Ardenweald? Tell me everything.", objectives = "Return to Tal-Inara in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58725] = { id = 58725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sinkeeper", description = "This is a Bell of Remembrance. Before the recent... \"events\" we used them to beckon souls from the Crypt of the Forgotten to deem their fate. \n\nIf they are less arrogant than they were before, they may continue in the process. If not, they must spend additional time in the crypt.\n\nLet's put this one to use, shall we? It's pretty beat up, let's hope we can get at least one use out of it.", completion = "Thank you, {name}. You have helped that soul, even if it does not feel like it.", objectives = "Use the Bell of Remembrance to beckon a soul from the Crypt of the Forgotten. Then, deem the soul's fate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58726] = { id = 58726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thick Skin", description = "The Primus forged a fine blade, but it will do you no good in its current state.\n\nFortunately for you, I possess the skill to finish his work!\n\nThat being said, I will require materials. The other Chosen have been too preoccupied with their combat drills to assist me at the forge, even as they demand more weapons and armor.\n\nThat's where you come in. You want a new blade? You'll have to earn it.", progress = "Can't be that difficult, can it?", completion = "You work quickly, don't you? I could use more assistants like you.", objectives = "Collect 40 Pulsating Hide Scraps from Overgrown Masses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58727] = { id = 58727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Place To Call Home", description = "You didn't end up on my list... so, I guess we're friends... for the moment.\n\nRathan took the soul you freed to Butchers Block near the Seat of the Primus. \n\nLet us meet him there and plan our next step together.", completion = "This spot will do great for us. We can build new constructs, and a home for ourselves.", objectives = "Meet up with Rathan and Emeni at Butchers Block.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58737] = { id = 58737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magni's Findings", description = "As if gettin' the Forge back up and runnin' wasn't good enough, I think we may have found the key tae takin' out N'Zoth once and for all in the archives of Mogu'shan Vaults!\n\nYe might want tae be sittin' down for this one, champion.", progress = "Pay attention, champion!", completion = "Looks like we got a plan!\n\nNow tae see what Wrathion's got cookin' up tae find Ny'alotha.", objectives = "Learn Magni's findings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58740] = { id = 58740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Subjugated Serpents", description = "Where the Zan-Tien march, the warserpents are sure to follow.\n\nI cannot stress to you enough how dangerous these beasts are. It is a shame to see them subjugated by the mogu, but we cannot afford to let them run rampant.\n\nI need you to put them down before they can wreak havoc on our lines.", progress = "Have you taken care of the serpents?", completion = "It is unfortunate to see the cloud serpents cut down, but the Zan-Tien have driven them beyond recovery.\n\nDon't worry, we'll make them pay.", objectives = "Kill 4 Onyx Warserpents in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58741] = { id = 58741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cutting Stone", description = "One problem with waging war against other mogu is that weapons dull and break very quickly when used against foes of stone and metal. \n\nBeing the sole blacksmith among the Rajani, it is sometimes difficult to keep up with our warriors needs.\n\nIf you come across any weapons in your battles with the mogu, I'm sure I could put them to good use.", progress = "What have you found?", completion = "These weapons look to be in good enough shape.\n\nThey will serve our warriors well.", objectives = "Collect 10 Mogu Armaments in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58742] = { id = 58742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retinus the Seeker", objectives = "Defeat Grixis Tinypop in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
