quests[58748] = { id = 58748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Living Statues Are Tough", objectives = "Defeat Grixis Tinypop in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58749] = { id = 58749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flight of the Vil'thik", objectives = "Defeat Grixis Tinypop in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58750] = { id = 58750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take the Bull by the Horns", description = "I've carved out quite the reputation as a tauralus wrangler. Everyone needs a tauralus!\n\nYou do some work for me, and people will know who you are as well.\n\nTake this bone splinter and poke a few juicy nibblers. Use them to lure a tauralus to you, then ride it back to me.", progress = "You want to be famous? Get the tauraluses I wanted?", completion = "These are some good tauraluses. Thanks for the help, mortal!", objectives = "Ride 5 Bloodskin Tauraluses back to Dundae.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58751] = { id = 58751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Common Peril", description = "Each house in Maldraxxus has two barons. Before the fall of my first house--the House of Eyes--our margrave sent my fellow baroness to investigate suspicious behavior in the House of Rituals.\n\nI have not heard from her since. Either she has found something... or has become another casualty of their treachery. \n\nHer orders took her to the Decay in the east. If you can find the baroness, give her this summons. \n\nWe were not friends, she and I, but she is a formidable combatant. We could use her might.", progress = "Someone new...but someone familiar.", completion = "Be thankful I am the one you found here.\n\nOthers in Maldraxxus may not have seen the potential in your strength.", objectives = "Locate the lost baroness in the Renounced Bastille.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58754] = { id = 58754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champions of the Swarm", description = "It is clear that Shek'zara is fully committed to this invasion. Our scouts have spotted some of her greatest champions among the battlefield.\n\nAny one of these mantid could prove too much for the soldiers of the Golden Lotus to overcome. We must hunt them down and eliminate them ourselves.\n\nAre you in?", completion = "Impressive kill count. You almost kept up with me.\n\nMaybe next time, though.", objectives = "Defeat 3 rare mantid enemies in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58755] = { id = 58755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stashed Supplies", description = "The invading mantid have been making off with the Golden Lotus' supplies lately. They're probably hoping  they can starve us out.\n\nWell, they may be right if we can't get some of our supplies back. \n\nWhile you're taking the fight to the swarm, keep an eye out for anywhere they might have stashed our supplies. You'd be doing the Golden Lotus a big favor if you could recover some.", progress = "Did you manage to find our supplies?", completion = "You've found them! What luck!\n\nThese supplies will help us hold out against the mantid, maybe even long enough to drive them back! \n\nThe Golden Lotus owes you one!", objectives = "Collect 3 Golden Lotus Supplies from Ambered Caches in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58756] = { id = 58756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dread Menders", description = "The ambercasters are among the highest castes of mantid society. Through their magic, they can mend and form amber to their will, allowing hastened recovery of the mantid's forces after a battle.\n\nThey are strategic targets, and we should seek them out. \n\nCare to join us?", completion = "With no one to mend their wounded soldiers, it's only a matter of time before the swarm is driven back to the wastes.\n\nYou did well.", objectives = "Kill 6 Mantid ambercasters in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58757] = { id = 58757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testing the Untested", description = "During a swarm, the mantid send their youngest in great numbers against the enemy to test their mettle. Those who survive join the swarm as true warriors of the mantid.\n\nWe should do our best to ensure that they don't make it through this test.", completion = "The mantid are foolish to send such untested creatures against a well-prepared foe.\n\nMay this be a lesson they never learn.", objectives = "Kill 12 Vil'thik Swarmborn in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58758] = { id = 58758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rampaging Destroyers", description = "The last mantid swarm is still very fresh in the memory of the Golden Lotus. Prior to the advancement of the swarm, the mantid would send their massive kunchong to soften up the defenders' lines.\n\nIt would seem their tactics have not changed.\n\nWe must stop those kunchong if the Golden Lotus hope to mount a defensive against the swarm. I'm counting on you to strike them down.", progress = "Have the beasts been halted?", completion = "The kunchong are dangerous beasts. You are a brave {class} for taking them on.\n\nThe Golden Lotus thanks you.", objectives = "Kill 4 Kunchong Destroyers in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58759] = { id = 58759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Empress' Guard", description = "The Zara'thik are the empress' elite guard. Empowered with plundered Azerite, they will stop at nothing short of absolute conquest of all of Pandaria.\n\nIf we allow them to advance past the Serpent's spine, the Golden Lotus will be no match for them.\n\nStop them at the wall, {class}.", progress = "We must break the Zara'thik advance!", completion = "You seem to have halted their advance. That will have to do for now.\n\nI'll alert you if the situation worsens.", objectives = "Kill 8 Zara'thik mantid in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58760] = { id = 58760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blades of Amber", description = "The mantid are frail and easily broken, but the amber blades they wield are formidable.\n\nWith a bit of work, they could be reshaped into something suitable for the mogu.\n\nBring them to me, and I can see about repurposing them to service the Rajani.", progress = "Have you brought me some blades?", completion = "It surprises me how such a sharp and durable blade could be made from something as fragile as a tree.\n\nPerhaps we have something to learn from the mantid, after all.", objectives = "Collect 12 Amber Blades from Vil'thik mantid in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58761] = { id = 58761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushed Underfoot", description = "In the past, the mantid would safeguard their hatchlings in incubation chambers until they were ready to be tested in the swarm. \n\nThese Vil'thik are sloppy, however, allowing their larvae to scurry out in the open. \n\nWouldn't it be a shame if someone crushed them?\n\nNo, of course it wouldn't.", completion = "Ah to see the future of your enemy crushed underfoot.\n\nIt is a good feeling, is it not?", objectives = "Squash 10 Vil'thik Larvae in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58762] = { id = 58762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taken by the Swarm", description = "There's something different about this mantid swarm. Instead of just killing everything in sight like the mantid usually do, they've taken to capturing our defenders and holding them alive.\n\nI really don't want to know what they have in store for the captives. \n\nWhy don't you go rescue them so we don't have to find out?", completion = "You've freed them? Oh, thank goodness!\n\nI cannot fathom what a mantid would want to do with live prisoners, but it cannot be good!", objectives = "Free 6 Golden Lotus prisoners from Hardened Amber Cages in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58763] = { id = 58763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halting Production", description = "The mantid use amber in nearly all aspects of their lives, from the structures they live in to the weapons they wield. Of course, I'm more interested in the latter.\n\nIf we can deprive the mantid of their materials, we will deprive them of their means to create implements of war.\n\nFind where they keep their amber and make sure they are unable to use it.", completion = "Without their precious amber, the mantid will be unable to resupply.\n\nWell done, {class}.", objectives = "Destroy 6 Amber Vessels in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58764] = { id = 58764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Standards of the Swarm", description = "The brazen mantid think they've already won. Even now, they fly banners along the Serpent's Spine, announcing their dominance.\n\nThey must learn that Pandaria belongs to the pandaren.\n\nBurn their banners down.", completion = "Their marks have been erased from the Vale. Soon, so will their forces.\n\nI hope to fight by your side when we finally drive them back over the Serpent's Spine.", objectives = "Burn 6 Zara'thik Banners within the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58765] = { id = 58765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siege Breaker", description = "The Golden Lotus can hold their own against the mantid's warriors, of that I have no doubt. Their war wagons, on the other hand, have the capability of crippling an entire squad of our fighters in a single volley.\n\nIf we wish to maintain the upper hand in this battle, we will need someone to infiltrate their positions and sabotage their siege engines.\n\nI would like you to volunteer.", completion = "Our scouts have reported several mantid war wagons seem to have been destroyed in spectacular fashion.\n\nI assume I have you to thank for this.", objectives = "Sabotage 3 Vil'thik War Wagons in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58769] = { id = 58769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME", description = "Suddenly the lack of fae and souls makes much more sense. These vile creatures must have taken them as they took my husband.\n\nBut I will get them back. If you are our new champion then you will help me for the good of Ardenweald.\n\n<Thiernas snorts.>\n\nDeath did not part us. I will not be torn from him now.", objectives = "Ride with Thiernax after the Drust.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58771] = { id = 58771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Directions Not Included", description = "Look at this place! What a mess. The Locus is inactive and these \"Forsworn\" have taken over.\n\nWe need to restore the Locus, but I do not know how. This place is not of my design, built long, long ago.\n\nLuckily, the previous Forgelite Prime was prolific. Recorded everything! If we can find her designs, I can certainly work it out. Even without Mnemis's help.\n\nLook around. Plenty of scrolls strewn about. Meet me near the Locus when you find what I need.", progress = "You find correct scroll?", completion = "You found it! And other interesting tomes as well. They will be properly catalogued when we are done.", objectives = "Find the Locus Manual among discarded scrolls in the Mnemonic Locus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58773] = { id = 58773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thornspeaker Captive", description = "Good to know the old bear hasn't forgotten me.\n\nUnfortunately, neither have the Drust. I was enjoying a peaceful afterlife before they showed up.\n\nDo not bother trying to force open this cage. You can only unlock it with three separate keys, and each one is held by a different Drust commander.\n\nThey should be somewhere nearby. Find them.", progress = "I would love to help you, but as you can see... I am not exactly free to leave.", completion = "The Drust locked me in this cage and dragged Kivarr away! If you release me, I can show you where they went!", objectives = "Rescue Kivarr from Eventide Grove in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58775] = { id = 58775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet the Queen", description = "{name}, we need only one more piece to complete the Crest of Ascension.\n\nEons ago, our Crest was originally crafted with the assistance of the fae. Deep within Ardenweald lies a portal they maintain to ferry souls back to their worlds. It is a source of great power and the final key to rebuilding the Crest.\n\nSeek out the Winter Queen in Ardenweald and plead our case. We've already sent Pelagos ahead as our envoy to arrange for your meeting.", completion = "We have lots of work ahead of us.", objectives = "Gain an audience with the Winter Queen at the Heart of the Forest in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58776] = { id = 58776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hatching Problems", description = "The aqir are multiplying faster than we can put them down. If this pace continues, we will be outnumbered before long.\n\nThe only way to slow down their assault is to attack their hives directly and destroy their eggs, but we have been unsuccessful in doing so.\n\nThat's why I wish to conscript your services.\n\nWill you help?", completion = "Destroying those eggs should buy us the time we need to regroup before they can throw another wave at us.\n\nYour may just mean the difference between victory and defeat.", objectives = "Destroy 6 Aqir Egg Clusters in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58777] = { id = 58777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Put Your Foot Down", description = "<Zahra stomps on a slimy, slug-like creature as you approach.>\n\nYou see that? Doesn't look like much, but believe it or not, those bugs grow out of these things.\n\nThey're all over the places the aqir have taken over, feeding off of our dead and growing into these monstrosities.\n\nIf you happen to see any of them, do the world a favor and take your boot to 'em.", completion = "By the looks of your boots, I'd say you stomped out a good number of those creepy crawlies.\n\nDon't worry, it'll clean off... eventually.", objectives = "Squish 8 Aqir Larvae in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58778] = { id = 58778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getting Ahead", description = "Morale's been down at the camp lately. Funny how getting chewed on by some bugs can spoil the mood of a place.\n\nI've got an idea to perk the troops back up, though. We need a trophy!\n\nSee if you can get me the head of one of those big tanky-looking ones so we can put it on display to show these bugs that we mean business! Just try to make sure it's not too mangled, okay?", progress = "Show me what ya got!", completion = "Wow, that thing is massive!\n\nIf a giant severed bug head doesn't lift the troops' spirits, I don't know what will!", objectives = "Collect 1 Goliath Trophy from Aqir Goliaths in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58779] = { id = 58779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking the Skies", description = "I'd like to see if we can get some more of these flyers in the air to drive back the aqir, but it's nearly impossible to get back to the Obelisk of the Sun with all these bugs in the air.\n\nI think we're going to have to thin them out on the ground before we can hope to gain aerial superiority.\n\nCan I count on you to lend a hand?", progress = "How fares the bug smashing?", completion = "The skies look a little clearer now, thanks to you. Hopefully it'll be enough to get our aerial efforts off the ground.\n\nEither way, your help is appreciated.", objectives = "Kill 15 flying Aqir in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58780] = { id = 58780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heralds of the Hive", description = "The aqir that have assaulted our camp seem to mainly consist of their shock troops. However, our scouts who dare venture behind their lines have spotted a different kind of creature -- tall and thin, wielding dangerous void magic.\n\nMy instinct tells me that these creatures are the leaders behind this invasion. They should be seen as targets of opportunity, and cut down wherever they're met.\n\nAre you up to the task?", progress = "What do you have to report?", completion = "Even a hydra will die if you sever enough of its heads.\n\nRemember that as the battle rages on.", objectives = "Kill 5 Aqir Dominators in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58781] = { id = 58781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terrors from the Deep", description = "The Aqir threaten the livelihood of the Wastewanders with each passing day, but I have heard of greater terrors that have been unearthed with them.\n\nOur fighters are able, but I fear what might happen if one of these ancient terrors falls upon us. \n\nI know that you have experience putting down great foes. I would like to ask you to do the same for us. \n\nAfter all, we can hardly help protect the forge if we've been decimated by some long-buried monster.", completion = "Uldum is a degree safer today, because of you.\n\nI thank you on behalf of the Wastewanders.", objectives = "Defeat 3 rare Aqir enemies in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58782] = { id = 58782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Things Left Behind", description = "The invading aqir forced the Wastewanders to flee many of our settlements in Uldum. In our haste to escape, much was left behind.\n\nI understand you intend to take the fight to the beasts. While you're there, could you keep an eye out for any of the supplies we had to leave behind? \n\nYou can keep anything of use to you, of course.", progress = "Were you able to find anything?", completion = "You found the supplies? Thank goodness!\n\nThe desert nights can be punishing on the unprepared. These will help ensure our survival out here.\n\nThe Wastewanders owe you much, {class}.", objectives = "Collect 3 Wastewander Supplies from Infested Caches in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58785] = { id = 58785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smack and Grab", description = "Bonetooths are the backbone of Maldraxxus's armed forces. Those that have been trained well are in demand amongst all of the houses.\n \nI always need new bonetooths to train, but they can be rather difficult to collect.\n\nBring me some of the younger ones, and I will reward you greatly. Be advised that you may need to weaken them before you are able to capture them.", progress = "Bring me back some bonetooths!", completion = "I am pleased with your work!", objectives = "Capture 10 Neonate Bonetooths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58787] = { id = 58787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial of Ascension", description = "The Forsworn threat is ever looming, and our forces are dwindling. Now, more than ever, we need more Ascended.\n\nOur generous Archon has blessed us with a portion of our anima stores to ascend our top aspirants to join our forces.\n\nKleia is amongst the chosen, and thus must complete her final trial.\n\nAs Pelagos is not yet prepared to ascend, I request you be Kleia's partner for this process. It is arduous and should not be embarked on alone.\n\nShe must bear her first soul.", completion = "The Forsworn have taken the court. They are blocking us from our trial!", objectives = "Meet Kleia at the Court of Elation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58788] = { id = 58788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Censers of Guidance", description = "The Forsworn are going to great lengths to prevent us from ascension.\n\nThey mobilize to stand in our way, to dismantle our chances to partake in our rituals.\n\nThey have stolen the resources we need to start our trial. Defeat them and retrieve the incense they carry so that we may continue on this path.", progress = "Each censer will require considerable incense. We must make sure we gather enough.", completion = "Infusing this incense with our own anima shall lead us on our individual journeys.", objectives = "Collect 10 Incense of Guidance from Forsworn forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58789] = { id = 58789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Misguiding Mentors", description = "These aspirants... we trained together. Learned together.\n\nThe Forsworn have swayed them from the path, now leading them to their demise.\n\nThey betray the path. Take out the Ascended that lead these forces against us.", progress = "For an Ascended to use the trust their aspirants have in them...\n\nThey do not deserve their wings.", completion = "The sting of aspirants choosing to walk against the Archon's will is a feeling that will never be soothed.", objectives = "Kill Strategist Palladia and Instructor Herus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58790] = { id = 58790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Cross the Veil", description = "Pallessa found a scroll detailing the ritual.\n\nWe will need to take our positions and speak a chant, surrendering some of our anima with every word.\n\nYour presence is vital. I ask you to use the censers to burn the incense as we meditate. The rest should unfold on its own.", completion = "I see you are a being of this world. Kleia should be honored to have you at her side.", objectives = "Aid Kleia in the Rite of Guidance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58791] = { id = 58791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Day in the Life", description = "A Bearer's duty is to carry souls through the veil to Oribos, where they shall be judged and passed along to one of the realms of the Shadowlands.\n\nThis soul is ready to move on.\n\nDuring this trial, you will experience his final moments before his death.\n\nWhen you are prepared, you shall see how this soul passed.", completion = "Oh there you are, love. I've been looking for you!", objectives = "Witness Ben Howell's final moments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58792] = { id = 58792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where a Soul Belongs", description = "This soul is no longer tethered to his world of Azeroth.\n\nKleia must perform her duty and bear him to Oribos to be judged by the Arbiter.\n\nTake this vesper. When you are ready, it will call Ascended to ferry you back across the Veil to Oribos.\n\nGo in service.", progress = "It is the duty of all kyrian to ferry souls to Oribos.", completion = "I... need some time to process this.", objectives = "Use the Vesper of Veilflight to travel to Oribos, then witness Ben Howell's judgment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58793] = { id = 58793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faith Through the Darkness", description = "This drought is... so much larger than I imagined.\n\nWhy did nobody tell us?\n\nThe burden of this knowledge weighs heavy... do we bear souls to their eternal torture?\n\nWe must return home.", completion = "I am glad that Kleia has returned successfully to us. Though she questions, she is resolute in her duties.\n\nIf only I could say the same for all of the aspirants.", objectives = "Return to Adrestes in Elysian Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58794] = { id = 58794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stabbing Wasteward", description = "I've been finding a lot of tauralus corpses lately, and I know it's all because those bonetooths Caleesy loves so much!\n\nI spotted the one that's responsible for the slaughter just west of here. Get rid of it! \n\nAnd don't mention this to Caleesy!", progress = "I hope you put an end to that creature.", completion = "You've done fine work! Just don't tell Caleesy about it.", objectives = "Slay the Satiated Sawtooth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58795] = { id = 58795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ascended", description = "With success over their trials, our aspirants shall now start the next chapter of their afterlives.\n\nThey have proven themselves through eons of training and cleansing, and will now earn ascendance.\n\nAs each aspirant is called, I ask you and Pelagos to please assist by ushering them up. It is a tradition we have practiced for eons, reinforcing the bonds that we share.", completion = "The Forsworn, now?\n\nThis is an all-out attack!", objectives = "Assist Pelagos with the ascension ceremony.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58796] = { id = 58796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forsworn Onslaught", description = "Loyalty's betrayal shall not go unnoticed.\n\nBut while the Paragons defend the city proper, it is up to us to defend Elysian Hold.\n\nI am very wounded... but I will hold strong. Pelagos and I will protect the survivors. You must aid in pushing back this assault!", progress = "Devos... she goes too far.", completion = "And so the tides of battle turn.\n\nElysian Hold may be safe, but the Spires still need our aid!", objectives = "Repel the Forsworn invasion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58797] = { id = 58797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forged by Trial", description = "{name}, my friend.\n\nI have thought of you as an ally for some time now. The thrill I felt when you decided to join us in Bastion... I knew you would be a boon unto our ranks.\n\nOur bond has been forged by the trials we face. Without you, I could have fallen to my newfound knowledge as Achillon did.\n\nI wish to cement our bond. I would be honored to soulbind with you.", progress = "You are an important part in my journey. I respect you greatly, and hope you feel the same.", completion = "You, me, and our dear Pelagos.\n\nI challenge anybody to name a better team.", objectives = "Complete the soulbinding ritual with Kleia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58798] = { id = 58798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spires of Ascension", description = "Our task is not complete yet.\n\nWe may have pushed back the Forsworn here in Elysian Hold, but it was only a distraction to split our forces.\n\nThe Archon and the Paragons fight to retake the Spires themselves.\n\nWe cannot hesitate to aid them in this time of need!", completion = "This attack has taught us much. The Archon shall be convening with the remaining Paragons to discuss this Forsworn threat.\n\nWe shall call upon you once more when you are needed.", objectives = "Kill Devos, Paragon of Doubt in the Spires of Ascension.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58799] = { id = 58799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Prime's Directive", description = "All centurion are made to serve the kyrian.\n\nThat they now work against ME, the Forgelite PRIME, is an insult to all centurions in Bastion. Look at them! Praetors! Goliaths! All... PURPLE!\n\nI hereby give you permission and expressly order you to extract their cores. I will repurpose them in a fitting manner. I will reclaim their anima to power the Locus.\n\nI can build more. Do not pity.", progress = "You have the cores?", completion = "Excellent. Their anima will be put to better use.", objectives = "Collect 12 Centurion Cores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58800] = { id = 58800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mnemonic Locus", description = "<Mikanikos examines the scroll you retrieved for him.>\n\nRight, right.\n\nSoul mirrors and Locus are tied together. If we restore anima to mirrors, it should repair the Locus back to full functionality. Thankfully, the cores you brought should be sufficient.\n\nAll I need to do is enable conduits. Simple!\n\nWell? Go on. You know how to use these, yes?", progress = "I wait to hear the hum of anima, yes.", completion = "I love the hum of anima. It has been a long time since I have heard it in such abundance.", objectives = "Use the Anima Conduits to restore the Mnemonic Locus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58801] = { id = 58801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enter the Void", description = "<As your approach the idol, the dark shards you carry appear to melt into your hand. You are immediately overcome with unspeakable anguish. It quickly gives way to feelings of joy, serenity, and an overwhelming desire to... kill.\n\nA hissing voice creeps into your mind.> \n\nMy faithful servant. I will grant you but a small taste of my unimaginable power, all I ask in return is that you complete one simple task. Kill any who would oppose me, spare no one. Do not fail me...", objectives = "Without dying or leaving Void Wraith form, sacrifice 10 players to N'Zoth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58802] = { id = 58802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Incredible Egg", description = "<The aqir seem to have been in the process of empowering this egg with void magic.\n\nIt looks to be far from hatching, so it should be safe to study to find out what they were planning to do with it. \n\nSomeone in the Explorers' League might be interested in taking a look.>", completion = "Fascinating! You say that the aqir were trying to empower this egg?\n\nYou did the right thing by bringing this egg into my care. Just think of the wonders we'll uncover when it hatches!\n\nYou look worried.", objectives = "Bring the Voidtouched Egg to H'partho Adoros in Ramkahen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58803] = { id = 58803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Match the Hatch", description = "Don't fret, I'm sure no ill will become of hatching this creature. After all, the aqir can't be born evil, can they?\n\nOf course, we have no idea how to take care of such an egg. I will need you to do some investigating.\n\nHead back to the aqir hives and see if you can find any other, similar eggs. If we can observe how they're being treated, we might be able to apply those learnings here.", progress = "What have you learned among the aqir?", completion = "The eggs hatched while you were studying them, you say?\n\nThat's unfortunate, but it looks like you returned in one piece! \n\nI will study these notes and see if I can learn more about our little friend here. We may just find something that can help in the hatching process.", objectives = "Investigate 7 Voidtouched Eggs in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58804] = { id = 58804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Void Incubation", description = "Well one thing is for certain with this egg, it requires great amounts of void energy in order to thrive. \n\nIt is fortunate for us that an Old God is attacking Azeroth at this very moment, yes?\n\nNo? Oh...\n\nIn any case, there should be an abundance of void energy wherever N'Zoth's minions strike. You should head out and find some.", progress = "Have you found a reliable source of void energy?", completion = "Brilliant! The void energy emanating off these crystals will be perfect to incubate the egg.\n\nDon't worry, I'm sure there won't be any side effects from carrying those around.", objectives = "Collect 10 Crystallized Void in areas under assault by N'Zoth's forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58805] = { id = 58805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Continued Incubation", description = "The egg is doing well, but we're going to need more of those void crystals to keep it healthy.\n\nCould you go out and gather some?", progress = "Did you bring more void crystals?", completion = "Yes, this will do nicely.\n\nI will continue to tend to the egg and keep you updated on its progress.", objectives = "Collect 10 Crystallized Void in areas under assault by N'Zoth's forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58806] = { id = 58806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warmth of the Sun", description = "The desert nights in Uldum can get awfully cold. I fear for our little egg's ability to withstand these temperatures.\n\nThese Amathet to the East seem to have mastered the harnessing of the sun's energy. If we could borrow some of their expertise, we could use it to keep the egg nice and cozy.\n\nKeep your eyes open for something we can use.", progress = "Did you find anything among the Amathet?", completion = "You've found a solar collection device? Perfect!\n\nNow our egg will be nice and toasty through the chilly nights.", objectives = "Collect an Amathet Solar Collector in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58807] = { id = 58807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrapping Up", description = "One oddity I have observed about this egg is that it lacks the protective webbing commonly found throughout the aqir hives. \n\nI believe this webbing has protective qualities, and could be beneficial to our egg if we can acquire some.\n\nWhile you're out fighting the insects, see if you can't bring back some of their webbing so we can make a proper cocoon for our growing egg.", progress = "Did you find some suitable webbing?", completion = "Oh, this sure is sticky! It should do the trick, though.\n\nHere, give me a moment while I wrap the little guy up.", objectives = "Collect 30 pieces of Aqir Webbing from aqir casters in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58808] = { id = 58808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encased in Amber", description = "You know who would probably know a lot about how to properly incubate this egg? The mantid!\n\nOf course, they're too busy trying to kill us to share their expertise, but there might be another way to benefit from their knowledge!\n\nPerhaps we could repurpose one of their incubation chambers. That could help speed up this process, I'm sure!\n\nIf you could find and mark one for me, I could airlift it out of there.", completion = "This is perfect! \n\nWhat a cozy little home this will make for our egg.", objectives = "Mark an Amber Incubator for H'partho to airlift in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58809] = { id = 58809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shocking Technique", description = "I have heard tales that the mogu use lightning to speed up the growth of their cloud serpents. I wonder if the same principle could be used for our aqir friend?\n\nThere's only one way to find out! Go to the Vale of Eternal Blossoms and see if you can get the parts together so we can create our own lightning rods. \n\nIf they work the same as they do for the cloud serpents, it should speed up the hatching process significantly.", progress = "Were you able to collect the proper components?", completion = "I hope the mogu didn't give you too much trouble.\n\nIt will all be worth it, though, once we hatch our little friend here.", objectives = "Collect 8 Lightning Rod Components from the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58810] = { id = 58810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coming Out of His Shell", description = "It looks like our egg is ready to hatch! Isn't this exciting!\n\nCome, let us welcome our new little friend to this world.", progress = "Oh, the anticipation!", completion = "Isn't he marvelous?\n\nWe still have a long way to go until we have a full-grown aqir, but even in his current state he is a sight to behold!", objectives = "Watch the Aqir Egg hatch in Ramkahen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58811] = { id = 58811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Balanced Diet", description = "Now that our larva is hatched, we'll need to figure out what we can feed it to keep it healthy. \n\nIt would seem that the aqir are carnivores, but the only things I've seen them eat are... well... us.\n\nOf course, we can't feed our little friend people, so we'll have to find an alternative. Perhaps we could substitute animal meat?", progress = "He looks hungry, I hope you brought a snack.", completion = "It looks like animal meat is not his favorite. \n\nHe should be okay for now, we'll try something different later.", objectives = "Collect 12 Chunks of Meat from beasts in Uldum and the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58812] = { id = 58812, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meat Alternatives", description = "In the wild it is actually fairly common for insects to eat others of their species. I wonder if this rings true for the aqir as well.\n\nCould you bring back some meat from the aqir or mantid? We'll see if that's more palatable for our friend here.", progress = "I do hope this works.", completion = "Poor little thing, the insect meat gave him tummy troubles.\n\nWe'll have to try something else tomorrow.", objectives = "Collect 12 pieces of Insectoid Meat from Aqir, Mantid, or other insects in Uldum or the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58813] = { id = 58813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fetid Filets", description = "You know, it occurred to me that since this creature has been imbued with void energy, it may prefer a more... corrupted food source.\n\nI speak, of course, of the Minions of N'Zoth.\n\nIt's a long shot, but it's worth a try.", progress = "Who knew aqir would be such picky eaters?", completion = "Well done! Our little guy cleaned his plate!\n\nIt's a good thing, too. I was not looking forward to asking Phaoris for fresh tol'vir corpses.", objectives = "Collect 12 pieces of Corrupted Flesh from creatures in areas under assault by N'Zoth's minions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58816] = { id = 58816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getting Backstage", description = "The next thing we need to prepare the vessel is a set of Night's Veil Flowers.\n\nWe use these flowers in our ceremonies, but since the drought we've just used them as props in our plays. There are certainly some backstage at the Star Lake Amphitheater.\n\nI bet Moonberry is there for the rehearsal of their next play. As a bonus, this will work out quite nicely for me to get revenge on her.\n\n<Willowblossom flashes a wicked grin.>", progress = "Do you have the flowers?", completion = "Mission accomplished! This will be so funny. Ah, sweet revenge.", objectives = "Retrieve a Wreath of Night's Veil Flowers from backstage at the Star Lake Amphitheater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58817] = { id = 58817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Action Figures", description = "It occurs to me that our larva's current living situation is quite dull. We should try to find something to keep him entertained.\n\nAfter all, a happy larva is a healthy larva!\n\nI think the Amathet keep figures for worship of their gods. I'm sure they could also double as toys for our little friend here. See if you can find some!", progress = "Did you find any suitable toys?", completion = "Look how happy he is with his new toys!", objectives = "Collect 6 Amathet Figurines from Amathet creatures in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58818] = { id = 58818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bug Buddies", description = "Is it just me or does our little friend look lonely? It would make sense that aqir are social creatures, coming from a hive and all. It must be difficult for him not being around any of his kind.\n\nYou know, maybe you could find some friends for him. Nothing big and scary, of course, but perhaps some of the smaller scarabs could be safe enough to keep him company.\n\nWhat do you think?", completion = "Look, they're playing! At least, I think that's what that is.\n\nAnyway, having some friends should go a long way to keeping our larva healthy and happy. Well done!", objectives = "Catch 5 Docile Sandstone Hatchlings in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58820] = { id = 58820, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bindings of Fleshcrafting", description = "These are the Bindings of Fleshcrafting! They empowered the Primus to shape the very flesh and bone of Maldraxxus.\n\nWe must return them to their rightful place, so their power can bolster us all.", completion = "I can feel their power. Perhaps they will give us the advantage we need.", objectives = "Place the Bindings of Fleshcrafting upon the Statue of the Primus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58821] = { id = 58821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glorious Pursuits", description = "Perhaps Draka has forgotten her loyalties, but I will fulfill my mission.\n\nMy enemy--the lich Mor'Bitan--hides within the House of Rituals. For some reason, his underlings skulk in this marsh.\n\nWe have not learned why they are here, but my devoted have spotted Mor'Bitan's second-in-command, Mephiles the Loyal. He will have our answers.\n\nCollect him for me. Once you capture him, slay his kin. Weaken his resolve.\n\nI will prime my base for his interrogation.", progress = "Any luck?", completion = "A simple task for such a storied hero.", objectives = "Kidnap Mephiles the Loyal, then kill 6 Morbid Disciples to intimidate him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58825] = { id = 58825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Super Jelly", description = "My friends in the Golden Lotus have been telling me some interesting things about the new mantid swarm. Apparently they have developed a concentrated royal jelly that accelerates the growth of newly hatched mantid. \n\nIf this jelly works on mantid, logic would suggest it would work on aqir as well!\n\nSee if you can find a sufficient sample of this jelly to help with our larva's growth.", progress = "This gets me thinking.\n\nAfter we've raised this one, I wonder if we could hatch a mantid as well?", completion = "Just look at how he gobbled it up! \n\nLet's hope this does the trick.", objectives = "Collect 8 Concentrated Royal Jelly in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58826] = { id = 58826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bloody Treat", description = "I have heard that a clan of the mogu called the Dokani have mastered the harnessing of life force into a substance they call \"anima.\"\n\nIf this stuff is indeed life condensed into a liquid form, then it could have spectacular properties when applied to our aqir larva.\n\nGo see if you can bring back some of this anima in a form that we can use. We'll see if our little friend here likes it!", progress = "Have you returned with the anima?", completion = "He sure took a liking to that! I guess it helps that it's blood-flavored.\n\nI'll keep note of any changes the anima causes in our friend's growth.", objectives = "Collect 8 Vials of Purified Anima from Dokani mogu in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58829] = { id = 58829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Grow So Fast", description = "Look! Our little larva friend has entered the pupa stage! \n\nWait... it looks like he's ready to emerge. \n\nGo on, give him a hand!", progress = "Take care, our friend is likely still very fragile.", completion = "Congratulations! Our little larva is now a fully-fledged aqir hatchling!\n\nYou must be very proud.", objectives = "Help the Aqir Larva emerge from its cocoon in Ramkahen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58830] = { id = 58830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aqir Instincts", description = "In observing the aqir battling the Wastewanders, I have seen the newly hatched immediately join the aqiri assault. It would seem the need for combat is born into these creatures.\n\nWe should exercise this in our new hatchling, under your supervision of course. Take him out with you and show him how to fight our enemies. \n\nHe may not be able to fight for long, so don't call him until you're ready for training.\n\nWith luck, he will come to see us as part of his hive.", progress = "Take care of your hatchling. He will return here if he becomes too injured.", completion = "That must have been an exciting day for our little hatchling.\n\nHe'll need to rest up for now, but we can try again tomorrow!", objectives = "Use H'partho's Whistle to summon your Aqir Hatchling and battle enemies in Uldum or Vale of Eternal Blossoms. Fighting tougher and rarer enemies will help your hatchling grow faster.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58831] = { id = 58831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honing Instincts", description = "It looks like our little friend is anxious and ready to practice more combat.\n\nWould you care to show him the ropes?", progress = "How goes the training?", completion = "The little guy is tuckered out after your adventures. \n\nDon't worry, I can tend to him here while you're off saving Uldum.", objectives = "Use H'partho's Whistle to summon your Aqir Hatchling and battle enemies in Uldum or Vale of Eternal Blossoms. Fighting tougher and rarer enemies will help your hatchling grow faster.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58832] = { id = 58832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trinkle Trinkle Little Twerp", description = "<On the note are the scribblings for a plan to steal silkstrider larvae and cook them.\n\nIt is signed by someone named Trinkle.>", progress = "Have you taken care of that nasty Trinkle?", completion = "Nasty spriggan!", objectives = "Kill Trinkle the Silk Eater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58833] = { id = 58833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calling in All Favors", completion = "We were brought together by chance, but now we fight as one.\n\nOur victory today will be one for all Maldraxxi.", objectives = "Meet Draka and allies at the House of Rituals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58842] = { id = 58842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Curator", description = "I tasked the Curator with reacquiring the Medallion of Avarice.\n\nHowever, since her return from the Maw, her mind has become... a bit chaotic. Do be kind, will you?  \n\nI ask that you lend her assistance in her search. She is at the Crypt of the Forgotten.", progress = "I require your assistance, Maw Walker.", completion = "We must retrieve those mirror shards before Denathrius's lackeys do. \n\nIt is the only way to access the crypt I concealed my medallion within.", objectives = "Meet the Curator at the Crypt of the Forgotten.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58843] = { id = 58843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vault of the Archon", description = "Behind me is the entrance to the Vault of the Archon. As you can see, it is warded against all unauthorized intrusion.\n\nTo make yourself an authorized entrant, place the offerings you collected before the guardians. You may then browse the contents of the vault at your leisure.\n\nDo consider that such access is coveted among the Forsworn and is the sole focus of their efforts here. I advise preparing for combat.", completion = "I am very pleased to meet you. The Vault has not received visitors in some time.", objectives = "Gain entrance into the Vault of the Archon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58844] = { id = 58844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Before the Dawn", description = "We shall need all we can muster if this day is to be ours.\n\nGather them all. The Watchers, Bearers, Centurions, and Collectors. Tell them that their Archon calls for them.\n\nOur Paragons will clear a staging ground at the Court of Elation for the final assault.", completion = "I hope you are prepared, Maw Walker.", objectives = "Gather the Watchers, Bearers, Centurions, and Collectors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58846] = { id = 58846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Greater Good", description = "The Forsworn are our former brothers and sisters in arms...our former kin. But we must see this through.\n\nWe will hit them from all sides. Fight well, but do not forget that Lysonia is our ultimate objective. If she does not fall, then she will recruit more to their cause in time.\n\nFollow the path, {name}.", completion = "The day is ours at last, thanks to you.", objectives = "Defeat Lysonia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58847] = { id = 58847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kyrestia's Grace", description = "I remember this particular soul...Uther. Devos brought him before us some time ago. She pleaded her case about his soul having a connection to the Maw.\n\nShe then took him under wing, ascending him before he was ready. He became her other hand alongside Lysonia, as it were.\n\nHe may proclaim a change of heart, but we shall see. Place him under guard. He may stay by the Archon's grace, but I will not take any chances with one so...broken.", completion = "May Thenios's efforts be fruitful. I have never seen a soul so broken in all my eons.", objectives = "Escort Uther.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58854] = { id = 58854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Convene the Paragons", description = "We have defeated the Forsworn at every turn. Saved those not too far gone. Routed them from our blessed Archon's temples. Now only one remains.\n\nThe Temple of Loyalty.\n\nLysonia has grown desperate in defeat. Abandoned all we strive to uphold by embracing the Maw. She has rallied her most fervent loyalists to the temple, knowing we will come for her.\n\nWe shall need the Paragons to finish this. Summon them.", progress = "Without the Paragons we cannot prevail against Lysonia.", completion = "Now that the Paragons stand ready, we must rally the rest of our forces.", objectives = "Summon the Paragons to call them to action.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58856] = { id = 58856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Who Are You Fooling?", description = "We cannot conduct the ritual without a very special guest. He's a silkstrider larva named Grubby and he's my best friend.\n\nUnfortunately, the nasty spriggans took him! What's worse is they cast illusions on what they steal, so no one can take it back!\n\nThe spriggans often carry trickster powder. If you can take some of that stuff, I can reverse their illusions and rescue Grubby.", progress = "We need to find Grubby!", completion = "We found him!", objectives = "Loot Sicklethorn Trickster Powder from Sicklethorn spriggans to dispel illusions on Conspicuous Objects and find Grubby.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58857] = { id = 58857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeds Away!", description = "I think we have a problem. Plucking the seed from this root must have shaken some burrowed gorm awake. This isn't good!\n\nGrab on to me. I will fly us out of here, but we must stop the gorm before they overrun the local Vorkai defenses!", progress = "I can't believe this. Blue seeds, red seeds, flying faeries!", completion = "Okay, I think everything is finally ready, {name}.", objectives = "Stop the gorm from overrunning the Gormhive Defense Wall and then pouring into the rest of Ardenweald!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58858] = { id = 58858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Fetid Filets", description = "Our little guy is getting hungry again. \n\nCould you pick him up a quick bite to eat?", progress = "My, this thing has an appetite.", completion = "Excellent! This will make sure he grows up big and strong!\n\nLet's hope he doesn't try to eat us then!", objectives = "Collect 12 pieces of Corrupted Flesh from creatures in areas under assault by N'Zoth's minions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58859] = { id = 58859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Someone His Own Size", description = "While fighting alongside you no doubt provides excellent training for our hatchling, sometimes it is better to have him fight on his own against enemies his own size.\n\nI know of one such opponent nearby, observing the Amathet near the Obelisk of the Stars. You should seek it out.", completion = "I bet that was quite an exhilarating battle!\n\nWe should try to get some more training in tomorrow.", objectives = "Defeat Retinus the Seeker in a pet battle with your Shadowbarb Hatchling in your party.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58860] = { id = 58860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Big Bad Beetle", description = "It could do our hatchling some good to face off against another aqir, to learn what his kind are capable of.\n\nI have found an opponent who could provide a challenging fight.", completion = "Looks like we've got a tough little hatchling on our hands!\n\nThat should be enough training for today, though.", objectives = "Defeat the Aqir Sandcrawler in a pet battle with your Shadowbarb Hatchling in your party.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58861] = { id = 58861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mantids' Mettle", description = "Observing the combat techniques of the mantid may prove helpful for our hatchling's training, offering a different way to use the natural weapons of an insect.\n\nI have found a mantid opponent that our hatchling could face in the Vale of Eternal Blossoms. Take him there and see how he does.", progress = "How did our hatchling fare against the mantid?", completion = "It looks like our little guy learned much from his battle with the mantid.\n\nNo doubt he'll be ready to face fully grown opponents soon.", objectives = "Defeat the Vil'thik Hatchling in a pet battle with your Shadowbarb Hatchling in your party.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58862] = { id = 58862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Littlest Defender", description = "The Baruk mogu are known for animating ancient statues to serve as defenders of their territory. They are a resilient foe, and much can be learned from battling an enemy with such rigid defenses.\n\nFortunately, it seems like one of their Stoneshapers mistakenly animated a small idol. It has been discarded as useless to the mogu who made it, but it could prove a valuable training opportunity for our hatchling.\n\nFind this miniature defender in the Vale of Eternal Blossoms.", completion = "I knew our little hatchling could handle the mogu creation!\n\nHis prowess grows with each passing day!", objectives = "Defeat the Baruk Stone Defender in a pet battle with your Shadowbarb Hatchling in your party.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58863] = { id = 58863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Custom Order", description = "I think it's safe to say that our little friend is no long a hatchling, but a fully grown aqir! He's grown so much, in fact, he could even carry you into battle.\n\nWait, that's a marvelous idea!\n\nYou should speak with Blacksmith Abasi about getting a saddle made.", progress = "What do you need?", completion = "I am certain I can craft a suitable saddle for that creature.\n\nHowever, I am going to need your help with some things first.", objectives = "Speak with Blacksmith Abasi in Ramkahen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58865] = { id = 58865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Otherworldly Armaments", description = "To craft a saddle for your beast, I'll need some special materials. Mainly, it will require metals much lighter than what we have available.\n\nI have noticed that the Black Empire cultists carry with them weapons made from otherworldly materials, which are impossibly light and strong. \n\nIf you could retrieve some of their weapons for me, I may be able to melt down this metal and shape it into a saddle for the aqir.", progress = "Have you found my materials?", completion = "These weapons... they are both disturbing and fascinating.\n\nI will melt them down at once. Visit me tomorrow to claim your saddle.", objectives = "Collect 12 Black Empire Armaments from Black Empire cultists in Uldum and the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58866] = { id = 58866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Own Drone", description = "The saddle is complete. I can't say I enjoyed working with that corrupted metal, but in the end I can easily say this is the finest saddle I have ever crafted.\n\nI know it looks... aggressive, but I assure you that your aqir will find it quite comfortable.\n\nI hope it serves you well.", progress = "Was the blacksmith able to help?", completion = "I am impressed, this is beyond what I thought Abasi capable of.\n\nIt looks like our little friend is ready to fly the nest. Remember to take good care of him!\n\nAnd do visit once and a while.", objectives = "Bring the Otherworldly Saddle to H'Partho Adoros in Ramkahen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58869] = { id = 58869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for Hibernal Hollow", description = "This is where we make our stand. The Drust and their minions have us nearly overrun.\n\nBut we will not let them destroy Hibernal Hollow. Nor will they take our anima or our wildseeds.\n\nFight with us. Let us drive them out.", completion = "We have won the battle...\n\n...But I fear we may have lost Ysera.", objectives = "Win the Battle for Hibernal Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58871] = { id = 58871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broken Harts", description = "The curse on Qadarin is a powerful one.\n\nBut I will break it.\n\n<Thiernax snorts.>\n\nDeath did not part us. I will not be torn from him now.\n\n<Thiernax studies both you and Shandris with a serious look in his eyes.>\n\nLend me your aid, and in turn I will help you with your world's Night Warrior. I do not promise I can save her... but I will share all that I know.\n\nReturn to the Heart of the Forest and tell Lord Herne what has happened. We will meet there.", progress = "This is even worse than I had thought.", completion = "I bet those spriggan thought this would be pretty funny. Well, we're not laughing!", objectives = "Report to Lord Herne at the Heart of the Forest, then speak with Moonberry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58876] = { id = 58876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Flight", description = "<A small dragon emerges from one of the side chambers found within N'Zoth's great carapace. It appears confused.\n\nYou surmise that such chambers must have been used to corrupt the dragons, exposing them directly to N'Zoth's dark whispers. At a young age, they would be driven mad, moreso than any other members of the twilight dragonflight that you had met before.\n\nThere would be no turning back from such madness.\n\nBut maybe it's not too late for this one...>", completion = "I can sense great pain, confusion, and loss, within this little one. This poor creature has led a short, heartbreaking life.\n\nAs have many of my kind, at the hands of... others.\n\n<Wrathion looks pained for a moment.>\n\nSome day, little one, we will find ourselves again.\n\n<Wrathion touches the dragon's head and closes his eyes.>\n\nThere, your mind is cleared. \n\nThis one is still young, it has much to learn and much to see. I trust you will care for it?\n\nDo not let me down, hero.", objectives = "Bring the Spawn of Vexiona to Wrathion in the Chamber of Heart.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58877] = { id = 58877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death's Power Grows", description = "Listen closely, {name}. A time of great destruction lies on the horizon that will challenge our very existence. Now more than ever, we must rise to the defense of Azeroth.\n\nIt is for this reason I have expanded the ranks of my champions to include your people. Your sacrifice sets you apart from all others. Hold your head high. Forevermore, you will be a death knight of the Ebon Blade.\n\nNow swear your fealty.", progress = "Swear your fealty, {name}.", completion = "I accept your pledge. Serve us well.\n\nTo that end, new weapons worthy of a Knight of the Ebon Blade have been forged.\n\nChoose, my champion.", objectives = "Swear fealty to the Lich King.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58879] = { id = 58879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alpaca It Up", progress = "<Sniffs curiously in the general direction of your backpack, eyeing it intently.>", completion = "<Munches enthusiastically on the Gersahl greens, while humming gleefully.>" }
quests[58881] = { id = 58881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[58887] = { id = 58887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alpaca It In", objectives = "<The friendly alpaca stares at you earnestly, clearly grateful for continuing to bring its favorite snack. It seems eager to join your adventures in the desert.>", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58900] = { id = 58900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sure Bet", completion = "You have traveled far for this moment.", objectives = "Meet Anzio at the entrance to the Theater of Pain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58902] = { id = 58902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defender of Azeroth", description = "An excellent choice.\n\nTroubling times come. As one of the chosen few, it is both your burden and privilege to defend our world. It is a great honor.\n\nBut also know you will be met with the scorn of the ignorant. Oftentimes, mortals are incapable of seeing past our fearsome appearance. Ignore these fools and do what must be done.\n\nSpeak with your commander. Then, use his death gate to travel to the land of the living and choose your destiny.You will learn:", objectives = "Speak with Highlord Darion Mograine. Then, use the highlord's death gate to travel to Stormwind. Once there, visit Chromie.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58903] = { id = 58903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defender of Azeroth", description = "An excellent choice.\n\nTroubling times come. As one of the chosen few, it is both your burden and privilege to defend our world. It is a great honor.\n\nBut also know you will be met with the scorn of the ignorant. Oftentimes, mortals are incapable of seeing past our fearsome appearance. Ignore these fools and do what must be done.\n\nSpeak with your commander. Then, use his death gate to travel to the land of the living and choose your destiny.You will learn:", objectives = "Speak with Highlord Darion Mograine. Then, use the highlord's death gate to travel to Orgrimmar. Once there, talk to Chromie.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58904] = { id = 58904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shards of Corruption", description = "<You feel the pull of something dark and inhuman on your mind, it's writhing tendrils digging in, tugging at your sanity. You feel compelled to collect more shards... all of them.>", progress = "<The Idol tugs at your very being. Demanding you to touch it.>", completion = "<You feel a foreboding presence in your mind, it seems... very pleased.>", objectives = "Collect 20 Shards of Corruption.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58905] = { id = 58905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Picking Up Pelagos", description = "Pelagos should have the seed by now! Can't start the ritual without the seed. He's likely still at Claw's Edge.\n\nWe'll see you there!", completion = "Whoops. Wrong seeds. I hope we can still find a use for these.", objectives = "Meet up with Pelagos, Willowblossom, and Grubby at Claw's Edge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58908] = { id = 58908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding Your Way", description = "Stormwind has a lot to offer adventurers like us, but it's far too big to explore on foot. The captain has arranged for you to receive a mount to help you get around.\n\nShe said to speak with Curly at the stables in Old Town... but I can't seem to remember the way there.\n\nHave no worries, {name}! All we need to do is ask a guard for directions. If you ever need help finding something, the city guards will show you where to go.\n\nLet's ask a nearby guard for directions to the stable master in Old Town!", progress = "Welcome to the stables, {class}. I've been expecting you.", completion = "So you're the newcomer that I've been hearing so much about?\n\nMy name's Curly. It's a pleasure to meet you, {name}!", objectives = "Speak with Curly at the stables in Old Town.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58909] = { id = 58909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "License to Ride", description = "The captain said you'd be coming here to pick up your mount. I hope you didn't have any problems finding the place!\n\nNow, before you ride off into the sunset, you'll need to learn how to... well, how to ride! Luckily, we have a riding trainer right here!\n\nSpeak with Darlene Stokx when you're ready to learn how to ride.", completion = "Now that you've learned the basics, feel free to return any time you want to advance your riding skills or purchase additional mounts!", objectives = "Speak with Darlene Stokx to learn the Apprentice Riding skill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58910] = { id = 58910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Mithlos Falconbriar to learn more about specializations!", progress = "Greetings. Have you come to learn about combat specializations?", completion = "Excellent choice of specialization, {name}.\n\nFeel free to test out your new abilities on the training dummies outside.", objectives = "Speak with Mithlos Falconbriar to learn about combat specializations.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58911] = { id = 58911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Home Is Where the Hearth Is", description = "I don't know about you, but all this running around has got me thirsty!\n\nWhy don't we head over to the Pig and Whistle Tavern and rest our legs over some cool pints of moonberry juice?\n\nWhile we're there, speak with Meagan the innkeeper to make the Pig and Whistle Tavern your new home. That way, if you ever find yourself stranded without a flight master nearby, you can use your hearthstone to return to the inn.\n\nNot only is it faster than a gryphon, but you'll save a few copper in the process!", progress = "How can I help you today, {class}? Are you looking for a place to stay?", completion = "As long as the Pig and Whistle Tavern is your home, we'll keep the fire going for you while you're away!", objectives = "Speak with Meagan Tillman to make the Pig and Whistle Tavern your home.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58912] = { id = 58912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Urgent Meeting", description = "I've been looking for you all over Stormwind, {name}.\n\nThe captain has delivered her report to the king. It appears that Stormwind requires your service yet again.\n\nThe leaders of the Alliance have gathered together for a meeting at Stormwind Keep, and your presence has been requested by King Wrynn himself. I was instructed to find you and deliver the message without delay.\n\nIt has been an honor serving with you, {name}. May the Light bless you on your journey.", completion = "Excellent, you're here. King Wrynn and the others have been awaiting your arrival.", objectives = "Speak with Captain Garrick at Stormwind Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58914] = { id = 58914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Warrior's End", description = "Hey, {name}! You're a {class}, right? Maybe you can deal with this... situation.\n\nI was scouting the area with Lindie's device and saw a ghost who was offering power to any \"true\" warriors.\n\nI know you're still new at this, but why don't you try going over there? \n\nWe could use every advantage against these ogres.", completion = "You are no hero of myth and legend... but I see potential within you.\n\nStand still, and I shall share with you my mightiest technique.\n\nAnd then I implore you to end my suffering.", objectives = "Speak with the strange ghost at the Darkmaul Bridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58915] = { id = 58915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hjalmar's Final Execution", description = "You now wield my most powerful skill, young warrior. \n\nNow use it to finish me! These ogres trapped my spirit here long ago for daring to defy them.\n\nOnly through a glorious death will I finally be allowed to rest. \n\nIt is the only way I will see my brothers and sisters in the afterlife.", completion = "Sounds like you had an adventure! Where do you think that ghost went after you fought it?", objectives = "Slay Hjalmar the Undying. You must use Execute in order to truly kill him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58916] = { id = 58916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dread Priming", description = "Sire Denathrius has requested I help you prepare for the hunt. Every hunter must help prepare a soul here in the Grove of Terror.\n\nI have a stubborn soul here who's been quite uncooperative, Houndmaster Loksey. His time has come to be hunted.\n\n<The Fearstalker hands you a set of Hopebreaker Soul Chains.>\n\nDemoralize him. We can't let him leave here with any hope. The hunt is meant to break the souls so they become less... resistant to the processes of Revendreth.", completion = "This soul is nearly ready. \n\nWe have an opportunity to finish preparing this one and take care of a problem in the process.", objectives = "Prepare Houndmaster Loksey for the Penitent Hunt in the Grove of Terror.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58917] = { id = 58917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rogue's End", description = "A rogue from the lost expedition, Coulston Nereus, tried scouting the island for any threats after they made landfall.\n\nThe last time Henry saw him, he was headed for a cave not far from here.\n\nCan you make contact with Coulston? He may be able to help with our rescue mission.\n\nOh, and be careful when heading north. Alaria spotted a vicious bear roaming the area.", progress = "Did you get the roots? Make sure that bear is far away when you pick them.", completion = "Here's the secret to making these poisons. It took me ages to learn it.\n\nNow that I've taught it to you, it should be easy enough for you to make more whenever you need it.", objectives = "Use Stealth to sneak around and find the first expedition's rogue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58918] = { id = 58918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Huwerath" }
quests[58923] = { id = 58923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Paladin's Service", description = "I found something strange while using Lindie's Scout-o-Matic that you should probably know about.\n\nThe ghost of a paladin appeared on the hill nearby. She looked straight at the Scout-o-Matic and asked for you.\n\nI don't understand a whole lot about paladins and the Light, but I think you may not want to ignore her.", progress = "Greetings, {name}. It is good to finally see you.", completion = "Those who serve the Light will know its blessing. Accept this gift, {class}.\n\nCall upon it when your strength fails and when hope seems lost. The Light will protect you from harm.", objectives = "Speak with the paladin's ghost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58931] = { id = 58931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inquisitor Stelia's Sinstone", description = "You never truly escape your past, Maw Walker.\n\nEvery venthyr once entered Revendreth as a soul, burdened by the immoralities of their mortal lives.\n\nLike all souls, they carved their true names and most shameful transgressions into sinstones.\n\nKnowledge that intimate can be a potent weapon, if wielded properly.\n\nLocate the sinstones of the inquisitors aiding the Accuser so that you may kill them. Start with Stelia.\n\nAfter they're dead, bring me the Accuser's sinstone. I will deal with her myself.", progress = "Inquisitors hide their sinstones to protect themselves.", completion = "Good. Temel will know how to exploit this sinstone.", objectives = "Collect Avowed Crypt Keys and open crypts until you locate Inquisitor Stelia's Sinstone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58932] = { id = 58932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temel, the Sin Herald", description = "<Before flying away, Echelon shouted an additional command.>\n\nExpropriate Temel as well. He will know how to exploit the sinstone properly.", progress = "Temel will not come willingly.", completion = "<Echelon eyes Temel suspiciously.>\n\nI never liked this runt.", objectives = "Defeat Cryptkeeper Kassir to earn Temel's obedience.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58933] = { id = 58933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deadliest of Poisons", description = "You've got the poison. Now it's time to take out that ogre. Gutgruk the Tough.\n\nHe usually patrols around their citadel. Probably looking for your expedition as we speak!\n\nPoison your blades, then take that monster down.", completion = "We'll make sure Coulston Nereus is properly remembered for his sacrifice. \n\nIt's a good thing that poison stopped the ogre... otherwise we would've been in trouble!", objectives = "Kill Gutgruk the Tough.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58936] = { id = 58936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beast Control", description = "The Grove of Terror's dredbats have become aggressive due to the lack of anima caused by the drought.   \n\nThis is a formal request to cull their numbers. We must re-establish dominance over our creations.\n\n-Flockmaster Sergio", completion = "The balance is returning. Please accept this payment on behalf of myself and the other keepers of this place.", objectives = "Kill 6 Dredbats in the Grove of Terror.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58937] = { id = 58937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evil Grubbies", description = "Oh no! This place is littered with mites!\n\nThey are cute like Grubby, but they grow into horrible gorm! If we cleared some of them out, then the Sylvari will have less to fight against later.\n\nThey can burrow away, so it's best to burn them up with Pelagos' red seeds. They'll be good for something after all.", progress = "How many more are there?", completion = "It will be hard for them to return.", objectives = "Burn 20 Evolving Mites with Pelagos' Flamelash Seeds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58938] = { id = 58938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorm Ruin Everything", description = "These red seeds will still prove useful. They come from a very dangerous plant and are quite unstable. If we are going to recover the blue seed we really need, then these might help.\n\nLet's clear out some of these gorm and search for the real seed.", progress = "We need to clear a path.", completion = "These seeds aren't just useful, they're dangerous!", objectives = "Kill 10 mature gorm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58939] = { id = 58939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blue Seed", description = "I remember seeing a blue seed with red leaves nearby, but it was in a cave behind a wall of brambles. I didn't think of it at the time, but maybe you could use the red seeds to get us in?\n\nI wish I didn't mix up the instructions or we wouldn't be in this mess. But maybe it's all going to work out anyway. Let's go!", progress = "This has been quite the fun adventure. Wouldn't you say?", completion = "The seed!", objectives = "Find the cave entrance, get through the blockage of brambles, and obtain the Ripened Anima Seed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58941] = { id = 58941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alpha Bat", description = "Dredbats are quite useful to us. We make them just like stoneborn, but they lack their same... intelligence. With very little direction, they strike fear into stubborn souls' hearts.\n\nWith the anima drought, our dominion over them has waned. One, Duskterror, has wreaked the most havoc.\n\nThis presents us with an opportunity. Take this soul and draw her in. When she's weak, we can capture her for our own purposes.", progress = "Is Duskterror captured?", completion = "Now that Duskterror is captured, we have a little more control over these grounds.", objectives = "Hitch Houndmaster Loksey to the stake in the Grove of Terror. Then, weaken Duskterror to capture her.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58946] = { id = 58946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Divine's Shield", description = "This island has been cursed by necrotic magic. The Light can only just reach this place.\n\nCall upon its Divine Shield to step through the barrier before us unharmed and destroy this vile altar.\n\nShow the darkness on this island that you are protected by the Light's embrace.", progress = "Do you require aid? Use Divine Shield to safely pass through the necrotic barrier.", completion = "You have done well, {name}. Dispel this foul magic wherever you encounter it.\n\nMy task has been fulfilled. The Light calls to me. \n\nGood luck, and remember that the Light's warmth will always embrace you.", objectives = "Cross the necrotic barrier with Divine Shield and destroy the Necrotic Altar. You can speak with Yorah if you need to reduce Divine Shield's cooldown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58947] = { id = 58947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test Your Mettle", description = "Many of the greatest Maldraxxi legends earned their fame fighting in the Theater of Pain. \n\nIf you want to follow in their footsteps, you need to prove you have what it takes to survive in there.\n\nDefeat Valuator Malus and Tester Sahaari in combat. Let's see what you can do!", progress = "Earn the right to proceed!", completion = "You've proven yourself worthy! I'll see if we can get you into a fight soon!", objectives = "Valuator Malus and Tester Sahaari defeated.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58948] = { id = 58948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Food on the Table", description = "I'm making a stew for dinner tonight, but it seems we're missing rabbit meat.\n\nWould you be able to go out back and collect some for me?\n\nOh and do be careful, I heard howling earlier. The wolves aren't normally out during the day.", progress = "Shh shh, Gwendolyn. It's okay, baby girl.", completion = "This should be plenty. Thank you, love.", objectives = "Collect 4 Rabbit Meat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58949] = { id = 58949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Millie's Garden", description = "Alma came by earlier and gave Millie some flower seeds to plant out in the garden.\n\nI love that our daughter is taking an interest in gardening, but I don't have time to wash her dress when she gets it covered in mud again!\n\nWould you help her with the digging so that she doesn't get too dirty?", progress = "<Millie giggles.>\n\nHi daddy!", completion = "You're the best daddy ever!\n\n<Millie gives you a big hug around the knees.>\n\nHere, I made you some lemonade. I only have enough for one glass, so don't drink it too fast!", objectives = "Use your shovel to till 3 Untilled Soil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58950] = { id = 58950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lumber for Lakeshire", description = "Magistrate Solomon requested a bundle of wood for his hearth. However, he's been too busy to come by and retrieve it.\n\nIf you wouldn't mind running it down to him at the town hall, I'm sure he'd appreciate it.", progress = "The folks are on edge, Ben. It's my job to keep them at ease.", completion = "Thanks for delivering the lumber. I was going to go pick it up myself, but the townsfolk have been crying wolf all day.", objectives = "Bring the Bundle of Lumber to Magistrate Solomon at the Lakeshire Town Hall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58951] = { id = 58951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lakeshire's Last Stand", description = "There's no time to evacuate... not if the Scourge are here!\n\nBoard the windows! Get everybody inside! Our only hope is to hide.", completion = "This poor soul.\n\nAn honest man... to die so gruesomely...", objectives = "Make a stand against the Scourge invasion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58952] = { id = 58952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Purging Flames" }
quests[58953] = { id = 58953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Priest's End", description = "You're a trained priest, right {name}? This might be up your alley.\n\nWe've spotted the bodies of other recruits from our expedition.\n\nI'm guessing they washed up on a different part of the island. They didn't make it very far.\n\nWhen you have a moment, could you say a few prayers over them? Just to help put their spirits at ease.\n\nWe'll give them a proper burial once we deal with the ogres.", completion = "There's no time fer chatting. I'm going tae bless ye with the power to resurrect.\n\nI'd give ye a bit more ceremony, but we got an urgent problem on our hands.\n\nIf we don't hurry, the souls of these poor recruits will be consumed by the ogre's necromancy!", objectives = "Find the corpses of the first expedition recruits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58960] = { id = 58960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resurrecting the Recruits", description = "The souls of these recruits aren't strong enough tae resist the dark magic bein' practiced on this island.\n\nUse Resurrect on the remains of these recruits. Beseech the Light tae give 'em another chance while their souls still linger.\n\nI've been stranded on this island for years, watchin' these ogres get away with all of this.\n\nIt's time tae make a stand.", progress = "Get goin' and save those recruits with resurrect!", completion = "Ye've got what it takes tae become a great {class} one day.\n\nMe? Oh, me body is long since decayed. But I can rest easy now that I know these ogres are going tae be stopped.", objectives = "Resurrect the Expedition recruits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58961] = { id = 58961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ambushed Settlers" }
quests[58962] = { id = 58962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Warlock's Bargain", description = "While you were mowing down hordes of undead, I was scouting more of the area with Lindie's device.\n\nI saw what looked like a portal out near the bridge, along with the corpse of a warlock we thought was lost in the shipwreck.\n\nThink you can go investigate the area and try to close that portal? We have enough problems on this island as it is.", progress = "I see you have the grimoire that enacted the binding ritual.", completion = "Our bargain has been struck.\n\nCall upon me from the Void, and I will answer.\n\n<The voidwalker looks at the worgen's corpse.>\n\nLet us see if you are stronger than those who came before you.", objectives = "Investigate the first expedition warlock's corpse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58974] = { id = 58974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ambushed Settlers" }
quests[58975] = { id = 58975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pest Removal" }
quests[58976] = { id = 58976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chasing a Memory", description = "The attack on the Temple of Purity is unprecedented in Bastion. At least, to my knowledge.\n\nWe need to know more. The fragment that the Paragon captured may contain the answers we seek.\n\nThere is a place nearby called the Mnemonic Locus. There, aspirants and ascended alike can call forth their memories and store them away. If we can look through this fragment's memories, perhaps we can learn more about the so-called Forsworn and, with luck, uncover their plan.\n\nI will meet you there. Go in service.", completion = "<Mikanikos gestures irritably toward the Forsworn behind him.>\n\nAre you here to help fix THIS?", objectives = "Travel to the Mnemonic Locus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58977] = { id = 58977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's In a Memory?", description = "It may be possible to extract memories from fragment, but I worry they will not be useful. This is not whole kyrian, but a tiny piece! A weird, broken piece. It cannot even speak!\n\nWe will apply extractor and see what comes out. Extractor might explode. It might not. For this? Worth the risk, I think.\n\nDo not know what will emerge. Could be memories. Could be nothing. Could be something else. May try to fight you! Stay on your guard, yes? Collect all that look Forsworn.\n\nSpeak when ready.", progress = "Do you think we will get the information we need, {name}?", completion = "We did it. With any luck, her memories are within our grasp.", objectives = "Collect memories of the Forsworn from the Fragment of Lysonia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58978] = { id = 58978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lysonia's Truth", description = "If I had not seen it with my own eyes, I do not know that I would believe such a thing is possible.\n\nYou carry a significant piece of Lysonia within you, now. Go to the Soul Mirrors and open yourself to them. With luck, they will draw from her essence to draw forth a memory of the Forsworn.\n\nIf this works, we may know what they are planning within minutes!", completion = "<Mikanikos fumes silently.>", objectives = "Stand before a Soul Mirror and witness memories from Lysonia's past.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58979] = { id = 58979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I MADE You!", description = "I have had it with this insolence!\n\nI have an idea to reset this Mnemis's personality, but you will need to keep it busy.\n\nIt will try to fight you, through whatever means it posseses. I suggest you try not to perish. Kleia can hold her own, so hide behind her if so inclined.\n\nHop to it!", completion = "I hope you will forgive my behavior. I was not feeling quite like myself.", objectives = "Help Mikanikos reset Locus-Keeper Mnemis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58980] = { id = 58980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mnemis, At Your Service", description = "Greetings, I am Locus-Keeper Mnemis and I would be delighted to assist you.\n\nI recall that you are trying to access a particular memory. Due to the contents, that memory can only be viewed within the Vault of the Archon.\n\nIn order to gain access to the Vault, you must collect offerings for the two guardians who watch over it. I have hidden these offerings from the Forsworn, as they are not authorized to enter.\n\nThe Forgelite Prime is the only one among you who can grant authorization. How convenient!", progress = "Did you find the offerings of which I spoke?", completion = "Your search was fruitful. I am delighted to see you remain intact.", objectives = "Locate two offerings within the Walk of Recollection, then proceed to the Vault of the Archon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58981] = { id = 58981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hardened Hive" }
quests[58983] = { id = 58983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for Azeroth: Tides of War", description = "King Wrynn has called us together for an urgent war council.\n\nIt seems that there was some trouble with the Horde while we were away. The king was impressed with the valor and bravery that you demonstrated during our mission to Exile's Reach.\n\nNow that you've arrived, the meeting will begin without delay.", progress = "Thank you for coming.", completion = "The Horde have forced our hand yet again.\n\nThis cannot stand.", objectives = "Attend the War Council in Stormwind Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58989] = { id = 58989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runeforging 101", description = "As knights of the Ebon Blade, we must always be prepared for a variety of martial situations. To this end, the dark art of runeforging is yours to command. With it, runes of great power can be engraved upon your weapons.\n\nAbove us in the Heart of Acherus are runeforges. Visit one and use your power to imbue a weapon with a rune of power.", progress = "Have you emblazoned a rune upon your weapon, {name}?", completion = "Remember, runeforges exist in only a few locations, including Acherus and certain places within Icecrown. You may only emblazon your weaponry at a Runeforge.\n\nReturn whenever you desire to replace the rune. Until then, suffer well.", objectives = "Use the Runeforging ability in your spellbook to engrave a rune upon your weapon.\n\nYou may freely replace the engraving at any time, so long as you are near a Runeforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58990] = { id = 58990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Titanus Egg" }
quests[58991] = { id = 58991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curious Corruption", description = "<There appears to be something unusual about this particular item. Perhaps someone in the chamber can speak to its origin.>", progress = "Find something interesting?", completion = "Titanic Purification system available.", objectives = "Seek answers in the Chamber of Heart about the corrupted item.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58992] = { id = 58992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pie Not?", description = "I want to cook something warm, savory, and gooey!\n\nThat's right! I want to make a lovely bone marrow pie! When it's done, you'll be as full as a tick. I guarantee it! \n\nNow, just any old marrow won't do. I need the very best and rarest marrow.\n\nAnd that's where you come in! I need you to help Mama out and dig that marrow up. Yes... dig. \n\nOh and be ready to knock some heads. Maldraxxus doesn't take kindly to being carved up.", progress = "Is there any kind of pie that's not just the best? Blood pie, bone marrow pie, bone marrow jelly...", completion = "Well, if this isn't the best batch of marrow I've ever seen! \n\nMama is going to cook you a feast today!", objectives = "Collect 4 Maldraxxi Bone Marrow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58993] = { id = 58993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swarm Defense" }
quests[58995] = { id = 58995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Dreamed A Dream", description = "This is quite a ceremony, everyone is here. This ritual is essential to the recreation of the Crest of Ascension and the preservation of Bastion. \n\nWe owe the Winter Queen and Willowblossom a great debt. Someday, I hope we can repay them.", progress = "Do you have the vessel?", completion = "She's... she's gone.", objectives = "Witness the ceremony.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58996] = { id = 58996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abel's Fate", description = "Maw Walker, I have another task for you.\n\nSome time ago, I sent Soulwatcher Abel and a few others to slay some troublesome bonemaulers.\n\nThey have yet to return. Go find them, will you?", progress = "What became of Abel?", completion = "So they were defeated? And yet, you still stand.\n\nShame.", objectives = "Investigate Soulwatcher Abel's fate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[58997] = { id = 58997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bittersweet Prize", description = "I... I don't know what to say.\n\nAll that is left is to return Willo... the vessel... to Polemarch Adrestes in Bastion. This sacrifice must not be in vain.", completion = "You have brought the vessel we require for the completion of the Crest of Ascension. I understand it came at a great cost.\n\nWe must endeavor to repay our friends in Ardenweald one day.", objectives = "Deliver the Vessel of Ardenweald to Polemarch Adrestes at Elysian Hold in Bastion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59000] = { id = 59000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elements of Corruption", description = "Corruption behaves in mysterious ways. It spreads beyond Azeroth herself, touching our most intimate thoughts and sometimes corrupting various relics, as you've seen firsthand.\n\nThough I cannot speak to the effects of these matters directly, I am sure MOTHER has information surrounding these so-called items of corruption.", progress = "What have you discovered?", completion = "Titanic Purification system online.", objectives = "Speak with MOTHER to learn about corrupted items.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59002] = { id = 59002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shaman's Duty", description = "Greetings, young one. Your companions cannot see me. Only you, for you have been trained in the ways of a shaman.\n\nThe shadow energies of this island have ensnared my pack. I need your aid to free them.\n\nGather veil blossoms from the surrounding area. Burn them on the campfire and breath deep of their smoke.\n\nThen you will be able to see my packmates and release them from their bonds.", progress = "The veil blossoms shall grant you the sight you need to rescue my pack.", completion = "My pack and I are too weak to oppose the dark forces on this island.\n\nWe will use the last of our strength to grant you our power.\n\nUse it to rid the island of the ogres' necromancy.\n\nFree the countless souls they have trapped here.", objectives = "Gather 4 veil blossoms to burn on the campfire in order to rescue the ghost wolf's pack.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59003] = { id = 59003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Combustible Cocoons" }
quests[59004] = { id = 59004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Splash Damage", description = "The Jailer's troops use anima charged runes to empower their armor. Without those runes, the troops will be significantly weaker! \n\nI developed this special formula to remove tough laundry stains, but it should be capable of removing magical runes as well!\n\nSplash my Putrification Potion on Rune-hardened troops, the bigger the better! Then collect the runes that fall off, so I can extract their anima.", progress = "Have you cleaned things up?", completion = "Victory will be ours, Maw Walker!", objectives = "50 Anima Charged Runes collected off Rune-hardened Troops.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59007] = { id = 59007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soul Well" }
quests[59008] = { id = 59008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spriggan Snares", description = "I'm so glad you and Qadarin were passing by! These spriggans are crazy!\n\nGet me out of here!\n\nI was gathering some herbs from the garden when they nabbed me. I'm sure they've captured other souls, too!", progress = "This behavior is unexpectedly bold for the spriggans.", completion = "Capturing souls is a far more brazen act than the typical spriggan prank. I wonder what has changed...", objectives = "Free Cirrik and rescue 8 Captives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59009] = { id = 59009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Her Rightful Place", description = "Mor'Bitan has met his end... and a painful one at that.\n\nYour fortitude contributed in no small part to my success. You have earned my allegiance... for the time being. \n\nThere is much left to do, should you truly desire ownership of this realm.\n\nLet us regroup at the Seat.", progress = "Were you successful?", completion = "It is good to have allies. Even ones so stubborn.", objectives = "Return to the Seat of the Primus with your runeblade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59011] = { id = 59011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Death We Are Truly Tested", description = "Vyraz is the one who trapped me within the Maw. He has long been in league with the House of Rituals and the House of Constructs.\n\nNo doubt he intended to trap you within that hellish place as well.\n\nIt is time he be brought to justice for his treason. Stand with me, and we will face him as one.", completion = "We are struggling to hold the line. We need to act fast.", objectives = "Confront Vyraz about the death of Margrave Krexus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59014] = { id = 59014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "King of the Hill", description = "Loksey is ready. It is finally time to begin the hunt.\n\nTake him to Wanecrypt. The Fearstalker and the other hunters will be there already.\n\nHurry now. She does not like to be kept waiting.", progress = "Where's the soul?", completion = "Let us begin, shall we?", objectives = "Bring Houndmaster Loksey to the Fearstalker in Wanecrypt Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59015] = { id = 59015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hostile Recollection" }
quests[59016] = { id = 59016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Uldum", description = "Our objectives in Uldum are being interrupted by the influx of Alliance scum.\n\nClear as many of them out of the area that you find, then report back.", completion = "Good work, {class}.", objectives = "Slay Alliance within Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59017] = { id = 59017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Vale of Eternal Blossoms", description = "Our objectives in Vale of Eternal Blossoms are being interrupted by the influx of Alliance scum.\n\nClear as many of them out of the area that you find, then report back.", completion = "Good work, {class}.", objectives = "Slay Alliance within Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59018] = { id = 59018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Vale of Eternal Blossoms", description = "Our mission in Vale of Eternal Blossoms is being compromised by the Horde incursion. \n\nGet into Vale and take out as many as you can.", completion = "Good work, {class}.", objectives = "Slay Horde within Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59019] = { id = 59019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Uldum", description = "Our mission in Uldum is being compromised by the Horde incursion. \n\nGet into Uldum and take out as many as you can.", completion = "Good work, {class}.", objectives = "Slay Horde within Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59020] = { id = 59020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Third Fall of Kel'Thuzad", description = "The time has come to purge Maldraxxus of treachery.\n\nOur armies are rallied. Our allies stand ready. The machine of war is in motion.\n\nWe must win this battle, or all of the Shadowlands will be lost.", completion = "Kel'Thuzad escaped into the Banished One's hands, but at least his evil has been driven from Maldraxxus.\n\nWell fought, {name}. Now we focus on rebuilding our forces and restoring order to our realm.", objectives = "Remove Kel'Thuzad from Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59021] = { id = 59021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herald Their Demise", description = "Since the dawn of Revendreth, Temel has been charged with proclaiming the sins of souls for all to hear.\n\nEvery soul here, including venthyr, has been forced to endure his wrathful pronouncements on at least one occasion.\n\nHe will know how to wield Inquisitor Stelia's sinstone to break through her defenses.\n\nSimply command him to do so after you locate the inquisitor, and eliminate her.", progress = "Is the inquisitor dead?", completion = "The ward on the Accuser's sinstone is weakened by the inquisitor's death.\n\nBut we must kill both inquisitors before the ward will fully fall, and we can access the Accuser's sinstone.", objectives = "Order Temel to read from Inquisitor Stelia's sinstone, then kill her.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59023] = { id = 59023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ending the Inquisitor", description = "Inquisitor Vilhelm hides smugly in the back of the courtyard, flanked by several gargons and loyal venthyr.\n\nWe must kill him to break the ward on the Accuser's sinstone, so that Lord Chamberlain can use it in his battle.\n\nTemel will once again help you penetrate the inquisitor's defenses. Do not tarry.", progress = "Once the inquisitor is dead, the warding spell will be broken.", completion = "Lord Chamberlain confirmed the kill. We should hurry.", objectives = "Order Temel to read from Inquisitor Vilhelm's sinstone, then kill him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59025] = { id = 59025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Straight to the Heart", description = "The success of Mor'Bitan's treachery has made him complacent.\n\nLet him enjoy the feeling, for it ends here. We will lure him out with this ritual... and we will avenge my margrave.\n\nStand with me now, {name}. Together, we will make an example of this traitor.", progress = "He will regret crossing me.", completion = "Cursed lich--may his soul never be reborn.", objectives = "Kill Mor'Bitan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59042] = { id = 59042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Good Heart", description = "Despite the beliefs of most people, Emeni has a kind heart.  Err...at least she will have one, once you give it to her!\n\nI can think of no one better than you, Maw Walker, to give Emeni a new heart. Perhaps this will warm her blood towards you. You might become friends or even soulbinds!\n\nPlease select and place a heart in Emeni's construct.", progress = "I hope you chose well!", completion = "You've done it, the construct is completed. The Slaughter Daughter lives again!", objectives = "Place a heart in Emenis' construct.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59043] = { id = 59043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baker's Dozen", description = "Under this very tent, I've prepared delicacies that would make demigods cry tears of joy. I'm always in need of more baking supplies!\n\nThe brokers usually sell me eggs from parts near and far, but maybe this time you could help me out instead.\n\nYou familiar with gorm? Big insect-like creatures native to Ardenweald. Well, if you find me some eggs of theirs, I'll bake you up something nice in return! \n\nMama will even send Starchy to help you out.", completion = "Perfect! Mama just knew you had the skills to handle such a task!", objectives = "Travel to Ardenweald and collect 13 Hatchready Gorm Eggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59063] = { id = 59063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curses!", description = "Oh, dear me, this is terrible! Just terrible!\n\nI know precisely which awful curse afflicts that poor soul! But these damnable spriggans keep stealing my scrolls, scattering them all over and ripping them apart! \n\nNow the falls are overrun with all manner of dangerous magic!\n\nThe spriggans have the pieces of the scroll you need. Gather them along with a binding from one of the major hexes, and you can put it all back together.", progress = "Hmm... Yes, this looks like it could be the one.", completion = "I knew Dreyden would have the scroll we need. We don't have time to waste!", objectives = "Retrieve 5 pieces of Shredded Scroll from Rotbriar spriggans and a Tattered Binding from a Major Hex to create a Sealed Scroll of Soul Rot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59068] = { id = 59068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Secret Never Spoken", description = "The first reagent listed in the scroll is a secret never spoken.\n\nWell, that's easy. I know who has tons of secrets! Watcher Vesperbloom, our resident snoop. She keeps the Wild Hunt informed of any nefarious behavior that takes place in the forest.\n\nI know she'd be willing to give us a secret to save Qadarin's soul from dissolving in excruciating pain.\n\nI'll have Thiernax meet you wherever she's hidden them. It'll keep his mind off what's happening to his husband.", progress = "Whew! This page... It's seen sights no one should ever see.", completion = "You have no idea how tempted I am to open this and read it. Let's hurry up and create this counter-curse!", objectives = "Obtain a Secret Never Spoken from Watcher Vesperbloom's records.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59069] = { id = 59069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Token of Lost Love", description = "My sister, Alexstrasza, lost her prime consort, Korialstrasz, towards the end of our war with Deathwing.\n\nShe has loved many in her long life, but none as deeply as he. I know in my heart she loves him still.\n\nFind Alexstrasza in the Vermillion Redoubt and ask for a token of her lost love. It will surely prove a powerful reagent for the counter-curse.", progress = "My sister loves with all of her heart...", completion = "This figurine... I have not seen it since...\n\nI gave this to her when we first became Aspects. Our duties would draw us apart for the first time in our lives. To know that she has kept it all this time...\n\n<Ysera wipes her eyes.>\n\nWe will put it to good use.", objectives = "Speak with Alexstrasza at the Vermillion Redoubt in Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59070] = { id = 59070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sacrifice of Anima", description = "The last thing we need for this counter-curse is some attuned anima.\n\nOf course, we don't have much to spare. That means this is more of a sacrifice than it normally would be.\n\nBut you know what? The spriggans made this mess, so they should help clean it up. Some really nasty ones have been causing mischief in Tirna Scithe. They should have the anima we need.\n\nThiernax looks like he could use some nice, vengeful, therapeutic spriggan stomping. I'll have him meet you there.", progress = "Have you handled those spriggans yet?", completion = "HA! That will teach those spriggans! You mess with the mistrunner, you get the magical horn!\n\nNow we have the anima we need! And, conveniently, it's already attuned to the bad attitude of the one who cast the curse.", objectives = "Slay Spriggans in Tirna Scithe to collect Mischief-touched Anima.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59071] = { id = 59071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mending a Broken Hart", description = "We have all the reagents for the counter-curse!\n\nHurry up and cast it before Qadarin's soul is lost, and Thiernax refuses to help you, and Tyrande is doomed to die horribly in the Maw, and everyone is sad!\n\nBut no pressure.", progress = "I... I cannot thank you enough.", completion = "Were it not for your aid, Qadarin's soul would have been lost forever.\n\nI... I can do no less than offer my aid in return.", objectives = "Perform the counter curse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59076] = { id = 59076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Minions of Mayhem", description = "To all downtrodden and unappreciated hard workers of the Shadowlands: the time has come to rise up. Rise up and stick it to the fangs and the wings and the bonemen! Stick it to the brokers and the bossmons! I says we go into business for ourselves!\n\nCome to our secret meeting at the Ledge of Destiny.\n\nTo all not-downtrodden warlords, Maw Walkers, and morally flexible powerful denizens: We are currently hiring muscle. If interested, please attend. \n\nDon't tell the fuzz.", sourceObjective = "Attend the publicly posted \"Secret Meeting.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[59087] = { id = 59087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That Darn Fox!", description = "You! You there!\n\nI, Clarion Song, need your assistance. Yes, yes, give yourself a moment to bask in my glory.\n\n<Clarion Song gives you a moment.>\n\nDone? Good. I need you to catch a troublesome vulpin kit. He is positively barbaric! Running amok, causing havoc, ruining my beauty rest! He's using a concealing charm to make himself invisible, but I know it's him!\n\nMake yourself useful and catch that kit!", progress = "Well? Did you catch it?", completion = "You, you actually caught that little mongrel?\n\nWell! I am pleasantly surprised. Now hand him over. We are going to go right to his parent. I have a few choice words for the esteemed Lord Renard. Member of the court he may be, I am too impossibly valuable to be constantly pestered by this ragamuffin child!", objectives = "Find and Catch Renny the Vulpin kit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59120] = { id = 59120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renny the Vulpin", description = "<The small vulpin kit runs up to you with a cheerful bounce and an air of mischief.\n\nYou, it seems, are interesting. Interesting enough that this child of Lord Renard of the Court of Winter has decided to tag along with you.\n\nWhat could possibly go wrong?>", sourceObjective = "<For once it is easy to pick up the small vulpin.\n\nRenny gives you an unmistakable grin. This will be fine... right?>", sourceObjectiveStatus = "unverified-source-field" }
quests[59126] = { id = 59126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supply Chain", description = "My friend! I could sure use your expertise right now.\n\nOne of our wagon convoys was attacked nearby! It was transporting critical supplies... and new goods for me to sell! \n\nIt's important--no--vital, that we recover as much of that equipment as possible.\n\nSo, you ready to go? Let's head out and salvage what we can!", progress = "Did you find those items?", completion = "Atticus will set a box aside each week with spare supplies in case you need any of them.", objectives = "Secure the area and recover Atticus's Supply Ledger and 10 Ossein Battlemail", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59130] = { id = 59130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The House of Plagues", description = "The House of Plagues was the first to fall in this conflict. We believed its demise was the result of a careless accident. If only we had known the truth sooner...\n\nBut perhaps not all their knowledge was lost. Before you arrived, our scouts reported signs of movement near the wreckage of their necropolis.\n\nIf any survivors remain, we'd be wise to add them to our ranks. But approach with caution. The toxic fallout may have left them mad... or worse.", completion = "My apprentice! I have been searching everywhere for you!", objectives = "Search for survivors near the House of Plagues.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59147] = { id = 59147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hand of Purification", description = "Nikolon was not alone.\n\n<Eridia stares grimly out over the temple grounds.>\n\nLong have I toiled over the aspirants in my care. Long have I tended to this temple under my Paragon. To know that so many have fallen, alone, is a blow.\n\nBut this... wanton destruction! It will not stand.\n\nYou will be my hand, {name}. Go forth. End them. All of them.\n\nMy duty demands that I tend to those that remain. I will find you near the bridge when the way is clear.", completion = "Some stains must be scoured away.", objectives = "\"Cleanse\" the Temple of Purity by slaying enemies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59171] = { id = 59171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey Upon Them", description = "My mission cannot progress without a supply of anima. \n\nFortunately, the necromancers nearby have been kind enough to gather some into their maldracite crystals.\n\nYou will relieve them of those crystals. They may be reluctant to part with them, but I trust you can be... persuasive.", progress = "Do not fail me.", completion = "Yes, these will do nicely.", objectives = "Collect 3 Anima-charged Maldracite.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59172] = { id = 59172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War is Deception", description = "You have proven a useful ally, {name}.\n\nMephiles undoubtedly possesses a wealth of information for us. However, the House of Rituals is unforgiving when it comes to betrayal. He will not talk.\n\nNot that it matters. The House of Eyes has ways to... extract a prisoner's knowledge without the use of words.\n\nPlace the charged crystals around me. They will facilitate the interrogation.", progress = "Let us reveal the truth.", completion = "Draka may be content to forget our master, but I will not rest until he is avenged.", objectives = "Prepare to interrogate Mephiles the Loyal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59173] = { id = 59173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[59174] = { id = 59174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[59175] = { id = 59175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eternal Revenge", description = "<On the shelves there are hundreds of other phylacteries of varying shapes and sizes.\n\nMany bear names - this one specifically has a etching with the name Mor'Bitan.\n\nLady Vashj would be interested in this phylactery.>", objectives = "Take the phylactery of Mor'Bitan back to Lady Vashj.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59179] = { id = 59179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daughter of the Night Warrior", description = "In my dreams, I see many things. Elven souls tortured in the Maw. A warrior of the night consumed by vengeance.\n\nAnd... Ardenweald's destruction.\n\nThese visions are ever shifting... ever vague. But I believe Tyrande Whisperwind is key to saving the night elves, as well as this realm.\n\nShandris Feathermoon, Tyrande's daughter, is touched by dreams as well.\n\nEven now, she travels to the Eternal City. Find her. If anyone can reach the heart of Tyrande, it is her.", completion = "{name}? You are a welcome sight in this strange place. \n\nPerhaps you already know that I have come to find my mother.", objectives = "Find Shandris Feathermoon within Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59181] = { id = 59181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Maw", description = "I have not seen Tyrande since she departed for Icecrown... but I see her in my dreams. She stalks a nightmarish landscape, brimming with the might of the Night Warrior.\n\nSuch power is too much for any mortal to bear for long. I shudder to think of the toll it has taken on my minn'do.\n\nHighlord Fordragon has told me of the Maw. If you truly have braved its horrors before, then I ask that you guide me through them as well.\n\nWe must find Tyrande and convince her to let go of the Night Warrior's rage.", completion = "I have seen bits and pieces of this dark realm in my dreams. Tyrande roams this place.\n\nWe must find her.", objectives = "Take Shandris Feathermoon into the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59183] = { id = 59183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drifting Sorrow" }
quests[59184] = { id = 59184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Borr-Geth" }
quests[59185] = { id = 59185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entangling Web", progress = "I'm waiting.", completion = "He will not escape this time.", objectives = "Collect 8 jars of Maldracite Dust.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59188] = { id = 59188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vaunted Vengeance", description = "So you are from my baroness's home world? It must be a special one to breed such powerful individuals.\n\nThe necromancers here have already begun preparation for Mor'Bitan's ritual. We should capitalize on their progress. \n\nThree necromancers act as the ritual's architects. Should we acquire their drafts, we could modify them to suit our purposes.\n\nCollect the plans... and feel free to savor your victims' torment.", progress = "We are hopeful for your success.", completion = "Yes... They will be made to know our pain.", objectives = "Collect Ritual Drafts from the three Architects.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59189] = { id = 59189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Recovery of Tyrande Whisperwind", description = "The Night Warrior's power is tearing Tyrande apart. Such rage... it is consuming her.\n\n<Shandris is silent a moment.>\n\nAnd yet, my mother speaks true. We cannot leave the souls of my people to suffer.\n\nWe shall follow Tyrande into Torghast. We must find a way to save the spirits of the kaldorei.\n\nAnd in the process, pray that we can save my minn'do as well.", completion = "I cannot fault my mother's intent... but she will be consumed before she finds justice for our people.\n\nWe must find another way to bring her back.", objectives = "Enter Torghast to recover Tyrande Whisperwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59190] = { id = 59190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek Your Mark", description = "I see why Draka sent you in her stead--you accomplish what she could not.\n\nWe have all the pieces. Now, we must simply put them together.\n\nThe steps to the ritual are simple: place our fractured crystals in formation around the obelisk.\n\nThen comes the sigil--*our* sigil. Use the maldracite powder to draw a binding glyph at the obelisk's base.\n\nWhen you are through, return to me.", progress = "Work swiftly.", completion = "Vengeance is nearly ours.", objectives = "Prepare the ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59196] = { id = 59196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Go in Service", description = "We cannot waste any more time. We must get an audience with the Archon, before this next attack happens!\n\nWe need to find a way to get you to Elysian Hold... and quickly!\n\nHero's Rest is a place of respite for the aspirants of Bastion. You can see it floating above from across the fields.\n\nMeet me there when you can. I have a plan.", progress = "We must get moving.", completion = "The Polemarch? He is the right hand of the Archon!\n\nShe truly believes us. We still have a chance!", objectives = "Meet Kleia at Hero's Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59197] = { id = 59197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steward at Work", description = "Stewards are useful for many reasons.\n\nThey keep Bastion tidy, fix anything broken, and offer unrivaled companionship and support.\n\nYour new steward assistant should be able to repair the beacon. Then you can summon the Polemarch to Hero's Rest.", completion = "Kalisthene has vouched for you by allowing usage of the beacon. For that reason, you have my attention.", objectives = "Use Summon Steward to fix the Beacon of Invocation, then use it to summon Polemarch Adrestes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59198] = { id = 59198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Swift Wings", description = "Our revered Archon has decided to grace you with an audience.\n\nIt is your duty to present your discoveries to her, then follow her wise judgment.\n\nShe holds audience in Elysian Hold, part of the sprawling Spires of Ascension, the home of the Ascended.\n\nWe shall carry you there, for it is a place for those who can fly.", completion = "The Archon's chambers are just above. I urge you to practice extreme deference while in her presence.", objectives = "Fly with Adrestes to Elysian Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59199] = { id = 59199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kyrestia, the Firstborne", description = "I will escort you to hold audience with the Archon.\n\nI beseech you to present your information succinctly and directly.\n\nOur wise Archon will hear you and make a decision on the best course of action.", progress = "None shall doubt the Archon, in her infinite wisdom.", completion = "The Archon's grace is upon you, mortal.", objectives = "Speak with Adrestes to address the Archon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[59200] = { id = 59200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wards of Bastion", description = "Each temple of Bastion is protected by a ward here in Elysian Hold. As long as the wards hold, no malevolent force can launch an assault.\n\nIt is concerning that the Forsworn were able to attack Purity in such force...\n\nYour orders are to examine the wards. As long as they hold, Bastion stands strong.", progress = "The wards each protect one of the temples of Bastion. If a ward is not active, that temple stands vulnerable.", completion = "It seems the Forsworn are in our very midst, even in the Spires.\n\nWe must send aid to the Temple of Courage posthaste.", objectives = "Investigate the temple wards in Elysian Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
